INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('accipiter-nisus', 5106, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('accipiter-nisus', 'ka', 'სად არის მიმინო დაფიქსირებული საქართველოში', 'მიმინოს რუკა საქართველოს iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოყოფილი; სხვა შემთხვევაში რეგიონი გავრცელებულად არ ითვლება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'მიმინოს დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('accipiter-nisus', 'en', 'Eurasian sparrowhawk: where it is recorded in Georgia', 'The Eurasian sparrowhawk map uses public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; otherwise a region is not treated as part of the range. Record counts reflect observation effort, not population density.', 'Eurasian sparrowhawk observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('accipiter-nisus', 'ru', 'Где ястреб-перепелятник отмечен в Грузии', 'Карта ястреба-перепелятника использует публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте выделены только регионы с достаточным числом записей; в остальных случаях регион распространением не считается. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения ястреба-перепелятника и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('accipiter-nisus', 'tr', 'Atmaca Gürcistan''da nerede kaydedildi?', 'Atmaca haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler gölgelendirilir; aksi halde bölge yayılış sayılmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Atmaca gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('aegypius-monachus', 5382, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('aegypius-monachus', 'ka', 'სად არის სვავი დაფიქსირებული საქართველოში', 'სვავის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან, ხოლო სტატუსი ერთმანეთისგან გამოყოფს საკმარისი ჩანაწერების მქონე რეგიონებსა და რეგიონებს, სადაც ჩანაწერები ცოტაა.', 'სვავის გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('aegypius-monachus', 'en', 'Cinereous vulture: where it is recorded in Georgia', 'The cinereous vulture map combines Reptiles.ge editorial photo records with public iNaturalist observations. Regions are taken from the records-by-region table, and the status column separates regions with enough records from regions with too few records.', 'Cinereous vulture distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('aegypius-monachus', 'ru', 'Где чёрный гриф отмечен в Грузии', 'Карта чёрного грифа объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам, а статус отделяет регионы с достаточным числом записей от регионов, где записей мало.', 'Данные о распространении чёрного грифа и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('aegypius-monachus', 'tr', 'Kara akbaba Gürcistan''da nerede kaydedildi?', 'Kara akbaba haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; durum sütunu yeterli kaydı olan bölgeleri kaydı az olan bölgelerden ayırır.', 'Kara akbabanın Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('alectoris-chukar', 846, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('alectoris-chukar', 'ka', 'სად არის კაკაბი დაფიქსირებული საქართველოში', 'კაკბის რუკა იყენებს iNaturalist-ის საჯარო დაკვირვებებს საქართველოდან. რეგიონები აღებულია ქვემოთ მოცემული ჩანაწერების ცხრილიდან: რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოყოფილი, სხვა რეგიონებში ჩანაწერები ცოტაა. რეგიონული პოლიგონების გარეთ დარჩენილი წერტილები საერთო რაოდენობაში შედის, მაგრამ რეგიონს არ მიეკუთვნება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობასაც ასახავს და პოპულაციის სიმჭიდროვეს არ ზომავს.', 'კაკბის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('alectoris-chukar', 'en', 'Chukar: where it is recorded in Georgia', 'The Chukar map uses public iNaturalist observations from Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions have too few records. Points outside the map''s regional polygons remain in the total but are not assigned to a region. Counts reflect observation effort, not population density.', 'Chukar observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('alectoris-chukar', 'ru', 'Где кеклик отмечен в Грузии', 'Карта кеклика использует публичные наблюдения iNaturalist из Грузии. Регионы взяты из таблицы записей: на карте выделены только регионы с достаточным числом записей, в остальных записей мало. Точки вне региональных полигонов включены в общее число, но не отнесены к региону. Число записей также отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения кеклика и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('alectoris-chukar', 'tr', 'Kınalı keklik Gürcistan''da nerede kaydedildi?', 'Kınalı keklik haritası Gürcistan''daki herkese açık iNaturalist gözlemlerini kullanır. Bölgeler kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler gölgelendirilir; diğerlerinde kayıt azdır. Bölge poligonlarının dışındaki noktalar genel toplama dahildir, ancak bir bölgeye atanmaz. Kayıt sayısı gözlem çabasını da yansıtır, nüfus yoğunluğunu ölçmez.', 'Kınalı keklik gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('anas-platyrhynchos', 6930, NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('anas-platyrhynchos', 'ka', 'სად გვხვდება გარეული იხვი საქართველოში', 'გარეული იხვის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს. წყაროებით დადასტურებული რეგიონები და ინდივიდუალური საველე ჩანაწერები ცალკე ფენებია; ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და პოპულაციის სიმჭიდროვედ არ უნდა განვიხილოთ.', 'გარეული იხვის გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', NULL, NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('anas-platyrhynchos', 'en', 'Mallard: where it occurs in Georgia', 'The mallard map combines Reptiles.ge editorial photo records with public iNaturalist observations. Source-confirmed regions and individual field records are separate layers, and record counts reflect observation effort rather than population density.', 'Mallard distribution evidence and field records on a map of Georgia', NULL, NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('anas-platyrhynchos', 'ru', 'Где встречается кряква в Грузии', 'Карта кряквы объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist. Регионы, подтверждённые источниками, и отдельные полевые записи показаны разными слоями; количество записей отражает интенсивность наблюдений, а не плотность популяции.', 'Данные о распространении кряквы и полевые записи на карте Грузии', NULL, NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('anas-platyrhynchos', 'tr', 'Yeşilbaş Gürcistan''da nerede görülür?', 'Yeşilbaş haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve herkese açık iNaturalist gözlemlerini birleştirir. Kaynakla doğrulanmış bölgeler ile tekil arazi kayıtları ayrı katmanlardır; kayıt sayısı gözlem yoğunluğunu yansıtır, popülasyon yoğunluğu değildir.', 'Yeşilbaşın Gürcistan''daki yayılış kanıtları ve arazi kayıtları', NULL, NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('anguis-colchica', 145895, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('anguis-colchica', 'ka', 'სად არის ბოხმეჭა დაფიქსირებული საქართველოში', 'ბოხმეჭას რუკა საქართველოს iNaturalist-ის საჯარო დაკვირვებებს ეყრდნობა. გამოკვეთილი რეგიონები ჩანაწერების რეგიონული ცხრილიდანაა: რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოყოფილი, სხვა შემთხვევაში რეგიონი გავრცელებულად არ ჩაითვლება. დაფარული ან მიახლოებითი საჯარო კოორდინატი ჩანაწერს რეგიონს არ მიაკუთვნებს. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს. Tarkhnishvili et al. 2026 ამ ტაქსონს კანდიდატად ტოვებს; რუკის სტატუსი სახეობრივ რანგს არ ადასტურებს.', 'ბოხმეჭას დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('anguis-colchica', 'en', 'Colchis slow worm: where it is recorded in Georgia', 'The Colchis slow worm map uses public iNaturalist observations in Georgia. Shaded regions come from the records-by-region table: only regions with enough records are shaded on the map, and any other region is not. Obscured or approximate public coordinates do not place a record in a region. Record counts reflect observation effort, not population density. Tarkhnishvili et al. 2026 still treat this taxon as a candidate; the map status does not settle species rank.', 'Colchis slow worm observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('anguis-colchica', 'ru', 'Где колхидская веретеница отмечена в Грузии', 'Карта колхидской веретеницы основана на публичных наблюдениях iNaturalist в Грузии. Залитые регионы взяты из таблицы записей: на карте выделены только регионы с достаточным числом записей, в остальных случаях регион распространением не считается. Скрытые или приблизительные публичные координаты не относят запись к региону. Число записей отражает активность наблюдателей, а не плотность популяции. Tarkhnishvili et al. 2026 по-прежнему считают этот таксон кандидатом; статус на карте не утверждает видовой ранг.', 'Наблюдения колхидской веретеницы и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('anguis-colchica', 'tr', 'Kolhis yılan kertenkele Gürcistan’da nerede kaydedildi?', 'Kolhis yılan kertenkele haritası Gürcistan’daki herkese açık iNaturalist gözlemlerini kullanır. Taralı bölgeler, bölgelere göre kayıt tablosundan gelir: haritada yalnızca yeterli kaydı olan bölgeler taranır, diğer durumlarda bölge yayılış sayılmaz. Gizlenmiş veya yaklaşık kamuya açık koordinatlar bir kaydı bölgeye atamaz. Kayıt sayıları gözlem çabasını gösterir, nüfus yoğunluğunu değil. Tarkhnishvili et al. 2026 bu taksonu hâlâ aday sayar; harita durumu tür rütbesini karara bağlamaz.', 'Kolhis yılan kertenkelenin gözlemleri ve kayıt bulunan bölgeler, Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('aquila-chrysaetos', 5074, 'record-summary', 4);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('aquila-chrysaetos', 'ka', 'სად არის მთის არწივი დაფიქსირებული საქართველოში', 'მთის არწივის რუკა იყენებს iNaturalist-ის საჯარო დაკვირვებებს საქართველოდან. ცხრილში რეგიონი რუკაზე გამოიყოფა მინიმუმ ოთხი ჩანაწერით; ნაკლები ჩანაწერის მქონე რეგიონი მონიშნულია როგორც „ჩანაწერები ცოტაა“. ჩანაწერების რაოდენობა ასახავს დაკვირვების ინტენსივობას და არა პოპულაციის სიმჭიდროვეს ან ბუდობის სტატუსს.', 'მთის არწივის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('aquila-chrysaetos', 'en', 'Golden eagle: where it is recorded in Georgia', 'The golden eagle map uses public iNaturalist observations from Georgia. A region is shaded on the map with at least four records in the table; regions with fewer records are marked “Too few records”. Record counts reflect observation effort, not population density or breeding status.', 'Golden eagle observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('aquila-chrysaetos', 'ru', 'Где беркут отмечен в Грузии', 'Карта беркута использует публичные наблюдения iNaturalist из Грузии. Регион выделяется на карте при наличии в таблице минимум четырёх записей; регионы с меньшим числом записей отмечены как «Мало записей». Число записей отражает активность наблюдателей, а не плотность популяции или статус гнездования.', 'Наблюдения беркута и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('aquila-chrysaetos', 'tr', 'Kaya kartalı Gürcistan''da nerede kaydedildi?', 'Kaya kartalı haritası Gürcistan''daki herkese açık iNaturalist gözlemlerini kullanır. Tabloda en az dört kayıt bulunan bölgeler haritada gölgelendirilir; daha az kayıt bulunan bölgeler “Kayıt az” olarak işaretlenir. Kayıt sayısı gözlem çabasını yansıtır, popülasyon yoğunluğunu veya üreme durumunu değil.', 'Kaya kartalı gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('araneus-diadematus', 52628, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('araneus-diadematus', 'ka', 'სად არის ჩვეულებრივი ჯვრიანა დაფიქსირებული საქართველოში', 'ჩვეულებრივი ჯვრიანას რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან და რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოყოფილი.', 'ჩვეულებრივი ჯვრიანას გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('araneus-diadematus', 'en', 'European garden spider: where it is recorded in Georgia', 'The European garden spider map combines Reptiles.ge editorial photo records with public iNaturalist observations. Regions are taken from the records-by-region table, and only regions with enough records are shaded on the map.', 'European garden spider distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('araneus-diadematus', 'ru', 'Где обыкновенный крестовик отмечен в Грузии', 'Карта обыкновенного крестовика объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам; на карте выделены только регионы с достаточным числом записей.', 'Данные о распространении обыкновенного крестовика и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('araneus-diadematus', 'tr', 'Avrupa bahçe örümceği Gürcistan''da nerede kaydedildi?', 'Avrupa bahçe örümceği haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; haritada yalnızca yeterli kaydı olan bölgeler gölgelendirilir.', 'Avrupa bahçe örümceğinin Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('argiope-bruennichi', 50867, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('argiope-bruennichi', 'ka', 'სად არის არგიოპა დაფიქსირებული საქართველოში', 'არგიოპას რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან და რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოყოფილი.', 'არგიოპას გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('argiope-bruennichi', 'en', 'Wasp spider: where it is recorded in Georgia', 'The wasp spider map combines Reptiles.ge editorial photo records with public iNaturalist observations. Regions are taken from the records-by-region table, and only regions with enough records are shaded on the map.', 'Wasp spider distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('argiope-bruennichi', 'ru', 'Где Argiope bruennichi отмечена в Грузии', 'Карта Argiope bruennichi объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам; на карте выделены только регионы с достаточным числом записей.', 'Данные о распространении Argiope bruennichi и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('argiope-bruennichi', 'tr', 'Argiope bruennichi Gürcistan''da nerede kaydedildi?', 'Argiope bruennichi haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; haritada yalnızca yeterli kaydı olan bölgeler gölgelendirilir.', 'Argiope bruennichi için Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('blatta-orientalis', 154213, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('blatta-orientalis', 'ka', 'სად არის შავი ტარაკანა დაფიქსირებული საქართველოში', 'შავი ტარაკანის რუკა აერთიანებს საქართველოს iNaturalist-ის საჯარო დაკვირვებებსა და Reptiles.ge-ის გალერეის კოორდინატიან ფოტოებს. რეგიონები აღებულია ჩანაწერების ცხრილიდან: რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოყოფილი; დანარჩენებში ჩანაწერები ცოტაა.', 'შავი ტარაკანის გავრცელების მტკიცებულებები და iNaturalist-ის საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('blatta-orientalis', 'en', 'Where the Oriental cockroach is recorded in Georgia', 'The Oriental cockroach map combines public iNaturalist observations from Georgia with georeferenced Reptiles.ge gallery photos. Regions come from the records-by-region table; only regions with enough records are shaded on the map, while others have too few records.', 'Oriental cockroach distribution evidence and iNaturalist field records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('blatta-orientalis', 'ru', 'Где чёрный таракан отмечен в Грузии', 'Карта чёрного таракана объединяет публичные наблюдения iNaturalist из Грузии и геопривязанные фотографии из галереи Reptiles.ge. Регионы взяты из таблицы записей: на карте выделены только регионы с достаточным числом записей, в остальных записей мало.', 'Данные о распространении чёрного таракана и полевые записи iNaturalist на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('blatta-orientalis', 'tr', 'Doğu hamam böceği Gürcistan''da nerede kaydedildi?', 'Doğu hamam böceği haritası Gürcistan''daki herkese açık iNaturalist gözlemlerini ve Reptiles.ge galerisindeki konumlu fotoğrafları birleştirir. Bölgeler kayıt tablosundan alınır; haritada yalnızca yeterli kaydı olan bölgeler gölgelendirilir, diğerlerinde kayıt azdır.', 'Doğu hamam böceğinin yayılış kanıtları ve iNaturalist arazi kayıtları Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('bufo-verrucosissimus', 21505, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('bufo-verrucosissimus', 'ka', 'სად არის კავკასიური გომბეშო დაფიქსირებული საქართველოში', 'კავკასიური გომბეშოს რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და საქართველოში გაკეთებულ iNaturalist-ის საჯარო ფოტოდაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან, ხოლო სტატუსი ერთმანეთისგან გამოყოფს საკმარისი ჩანაწერების მქონე რეგიონებსა და რეგიონებს, სადაც ჩანაწერები ცოტაა. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'კავკასიური გომბეშოს საველე ჩანაწერები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('bufo-verrucosissimus', 'en', 'Where the Caucasian toad is recorded in Georgia', 'The Caucasian toad map combines Reptiles.ge editorial photo records with public iNaturalist photo observations in Georgia. Regions are taken from the records-by-region table, and the status column separates regions with enough records from regions with too few records. Record counts reflect observation effort, not population density.', 'Caucasian toad field records and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('bufo-verrucosissimus', 'ru', 'Где кавказская жаба отмечена в Грузии', 'Карта кавказской жабы объединяет редакционные фотозаписи Reptiles.ge и публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей по регионам, а статус отделяет регионы с достаточным числом записей от регионов, где записей мало. Число записей отражает интенсивность наблюдений, а не плотность популяции.', 'Полевые записи кавказской жабы и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('bufo-verrucosissimus', 'tr', 'Kafkasya karakurbağası Gürcistan''da nerede kaydedildi?', 'Kafkasya karakurbağası haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; durum sütunu yeterli kaydı olan bölgeleri kaydı az olan bölgelerden ayırır. Kayıt sayısı popülasyon yoğunluğunu değil, gözlem yoğunluğunu yansıtır.', 'Kafkasya karakurbağasının Gürcistan haritasında arazi kayıtları ve kayıt bulunan bölgeler', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('bufotes-viridis', 1453013, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('bufotes-viridis', 'ka', 'სად არის მწვანე გომბეშო დაფიქსირებული საქართველოში', 'მწვანე გომბეშოს რუკა ეყრდნობა iNaturalist-ის საჯარო ფოტოდაკვირვებებს საქართველოდან. რუკაზე მონიშნულია მხოლოდ ის რეგიონები, რომლებსაც ჩანაწერების რეგიონულ ცხრილში საკმარისი ჩანაწერი აქვს; დანარჩენი წერტილები ცალკეული ჩანაწერებია. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'მწვანე გომბეშოს საველე ჩანაწერები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('bufotes-viridis', 'en', 'Where the green toad is recorded in Georgia', 'The green toad map uses public iNaturalist photo observations from Georgia. Only regions with enough records in the records-by-region table are shaded on the map; other points are individual records. Record counts reflect observation effort, not population density.', 'Green toad field records and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('bufotes-viridis', 'ru', 'Где зелёная жаба отмечена в Грузии', 'Карта зелёной жабы основана на публичных фотонаблюдениях iNaturalist из Грузии. На карте закрашены только регионы с достаточным числом записей в таблице записей по регионам; остальные точки — отдельные записи. Число записей отражает интенсивность наблюдений, а не плотность популяции.', 'Полевые записи зелёной жабы и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('bufotes-viridis', 'tr', 'Yeşil karakurbağa Gürcistan''da nerede kaydedildi?', 'Yeşil karakurbağa haritası Gürcistan''dan herkese açık iNaturalist fotoğraflı gözlemlerine dayanır. Haritada yalnızca bölgelere göre kayıt tablosunda yeterli kaydı olan bölgeler gösterilir; diğer noktalar tekil kayıtlardır. Kayıt sayısı popülasyon yoğunluğunu değil, gözlem yoğunluğunu yansıtır.', 'Yeşil karakurbağanın Gürcistan haritasında arazi kayıtları ve kayıt bulunan bölgeler', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('canis-aureus', 851014, 'record-summary', 1);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('canis-aureus', 'ka', 'სად არის ტურა დაფიქსირებული საქართველოში', 'ტურას რუკა იყენებს საქართველოში გადამოწმებულ iNaturalist-ის საჯარო ფოტოდაკვირვებებს. რუკაზე შეფერილია მხოლოდ რეგიონი, რომელსაც ქვემოთ მოცემულ ცხრილში საკმარისი ჩანაწერი აქვს; სხვა წერტილები ცალკეული ჩანაწერებია. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'ტურას საველე ჩანაწერები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('canis-aureus', 'en', 'Golden jackal: where it is recorded in Georgia', 'The golden jackal map uses reviewed public iNaturalist photo observations from Georgia. Only regions with enough records in the records-by-region table are shaded on the map; other points are individual records. Record counts reflect observation effort, not population density.', 'Golden jackal field records and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('canis-aureus', 'ru', 'Где шакал отмечен в Грузии', 'Карта шакала использует проверенные публичные фотонаблюдения iNaturalist из Грузии. На карте окрашены только регионы с достаточным числом записей в таблице; остальные точки — отдельные находки. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Полевые записи шакала и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('canis-aureus', 'tr', 'Çakal Gürcistan''da nerede kaydedildi?', 'Çakal haritası Gürcistan''daki incelenmiş herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Haritada yalnızca kayıt tablosunda yeterli kaydı olan bölgeler boyanır; diğer noktalar tekil kayıtlardır. Kayıt sayısı gözlem çabasını yansıtır, nüfus yoğunluğunu değil.', 'Çakalın Gürcistan''daki arazi kayıtları ve kayıt bulunan bölgeler', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('canis-lupus', 42048, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('canis-lupus', 'ka', 'სად არის მგელი დაფიქსირებული საქართველოში', 'მგლის რუკა იყენებს საქართველოში გაკეთებულ iNaturalist-ის საჯარო ფოტოდაკვირვებებს. რუკაზე შეფერილია მხოლოდ რეგიონი, რომელსაც ქვემოთ მოცემულ ცხრილში საკმარისი ჩანაწერი აქვს; სხვა წერტილები ცალკეული ჩანაწერებია. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'მგლის საველე ჩანაწერები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('canis-lupus', 'en', 'Where the wolf is recorded in Georgia', 'The wolf map uses public iNaturalist photo observations from Georgia. Only regions with enough records in the records-by-region table are shaded on the map; other points are individual records. Record counts reflect observation effort, not population density.', 'Wolf field records and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('canis-lupus', 'ru', 'Где волк отмечен в Грузии', 'Карта волка использует публичные фотонаблюдения iNaturalist из Грузии. На карте окрашены только регионы с достаточным числом записей в таблице; остальные точки — отдельные находки. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Полевые записи волка и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('canis-lupus', 'tr', 'Kurt Gürcistan''da nerede kaydedildi?', 'Kurt haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Haritada yalnızca kayıt tablosunda yeterli kaydı olan bölgeler boyanır; diğer noktalar tekil kayıtlardır. Kayıt sayısı gözlem çabasını yansıtır, nüfus yoğunluğunu değil.', 'Kurdun Gürcistan''daki arazi kayıtları ve kayıt bulunan bölgeler', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('capreolus-capreolus', 42184, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('capreolus-capreolus', 'ka', 'სად არის ევროპული შველი დაფიქსირებული საქართველოში', 'ევროპული შვლის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან, ხოლო სტატუსი ერთმანეთისგან გამოყოფს საკმარისი ჩანაწერების მქონე რეგიონებსა და რეგიონებს, სადაც ჩანაწერები ცოტაა.', 'ევროპული შვლის გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('capreolus-capreolus', 'en', 'European roe deer: where it is recorded in Georgia', 'The European roe deer map combines Reptiles.ge editorial photo records with public iNaturalist observations. Regions are taken from the records-by-region table, and the status column separates regions with enough records from regions with too few records.', 'European roe deer distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('capreolus-capreolus', 'ru', 'Где европейская косуля отмечена в Грузии', 'Карта европейской косули объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам, а статус отделяет регионы с достаточным числом записей от регионов, где записей мало.', 'Данные о распространении европейской косули и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('capreolus-capreolus', 'tr', 'Avrupa karacası Gürcistan''da nerede kaydedildi?', 'Avrupa karacası haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; durum sütunu yeterli kaydı olan bölgeleri kaydı az olan bölgelerden ayırır.', 'Avrupa karacasının Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('cheiracanthium-punctorium', 61866, 'record-summary', 1);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('cheiracanthium-punctorium', 'ka', 'სად არის Cheiracanthium punctorium დაფიქსირებული საქართველოში', 'Cheiracanthium punctorium-ის რუკა აერთიანებს Reptiles.ge-ის წყაროებზე დაყრდნობილ ჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან; ამ სახეობაზე ერთი ჩანაწერიც საკმარისია, რომ რეგიონი რუკაზე გამოიყოს.', 'Cheiracanthium punctorium-ის გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('cheiracanthium-punctorium', 'en', 'European yellow sac spider: where it is recorded in Georgia', 'The European yellow sac spider map combines Reptiles.ge source records with public iNaturalist observations. Regions are taken from the records-by-region table; for this species, a region with at least one record is shaded on the map.', 'European yellow sac spider distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('cheiracanthium-punctorium', 'ru', 'Где Cheiracanthium punctorium отмечен в Грузии', 'Карта Cheiracanthium punctorium объединяет записи из источников Reptiles.ge и публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам; для этого вида одного наблюдения достаточно, чтобы регион был выделен на карте.', 'Данные о распространении Cheiracanthium punctorium и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('cheiracanthium-punctorium', 'tr', 'Cheiracanthium punctorium Gürcistan''da nerede kaydedildi?', 'Cheiracanthium punctorium haritası Reptiles.ge kaynak kayıtlarını ve herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; bu tür için en az bir kayıt bulunan bölge haritada gölgelendirilir.', 'Cheiracanthium punctorium için Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('ciconia-ciconia', 4733, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('ciconia-ciconia', 'ka', 'სად არის თეთრი ყარყატი დაფიქსირებული საქართველოში', 'თეთრი ყარყატის რუკა საქართველოს iNaturalist-ის საჯარო დაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოყოფილი, დანარჩენში ჩანაწერები ცოტაა. ეს ჩანაწერები თავისთავად ბუდობას არ ადასტურებს. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'თეთრი ყარყატის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('ciconia-ciconia', 'en', 'White stork: where it is recorded in Georgia', 'The white stork map uses public iNaturalist observations from Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions have too few records. These observations do not by themselves establish breeding. Record counts reflect observation effort, not population density.', 'White stork observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('ciconia-ciconia', 'ru', 'Где белый аист отмечен в Грузии', 'Карта белого аиста основана на публичных наблюдениях iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте выделены только регионы с достаточным числом записей, в остальных записей мало. Эти наблюдения сами по себе не доказывают гнездование. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения белого аиста и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('ciconia-ciconia', 'tr', 'Leylek Gürcistan''da nerede kaydedildi?', 'Leylek haritası Gürcistan''daki herkese açık iNaturalist gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan gelir: haritada yalnızca yeterli kaydı olan bölgeler gölgelendirilir; diğerlerinde kayıt azdır. Bu gözlemler tek başına üremeyi kanıtlamaz. Kayıt sayısı gözlem çabasını yansıtır, popülasyon yoğunluğunu ölçmez.', 'Leylek gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('columba-livia', 3017, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('columba-livia', 'ka', 'სად არის გარეული მტრედი დაფიქსირებული საქართველოში', 'გარეული მტრედის რუკა საქართველოს iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოყოფილი; სხვა შემთხვევაში რეგიონი გავრცელებულად არ ითვლება. ეს ჩანაწერები გენეტიკურად ველურ ფრინველსა და ქალაქში თავისუფლად მცხოვრებ მტრედს ერთმანეთისგან არ ჰყოფს. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'გარეული მტრედის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'საკმარისი ჩანაწერების მქონე რეგიონი', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('columba-livia', 'en', 'Rock Dove: where it is recorded in Georgia', 'The Rock Dove map uses public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; otherwise a region is not treated as part of the range. These records do not separate genetically wild birds from free-living city pigeons. Record counts reflect observation effort, not population density.', 'Rock Dove observations and regions with records on a map of Georgia', 'Region with records', 'regions with enough records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('columba-livia', 'ru', 'Где сизый голубь отмечен в Грузии', 'Карта сизого голубя использует публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте выделены только регионы с достаточным числом записей; в остальных случаях регион распространением не считается. Эти записи не отделяют генетически диких птиц от свободно живущих городских голубей. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения сизого голубя и регионы с записями на карте Грузии', 'Регион с записями', 'региона с достаточным числом записей', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('columba-livia', 'tr', 'Kaya güvercini Gürcistan''da nerede kaydedildi?', 'Kaya güvercini haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler gölgelendirilir; aksi halde bölge yayılış sayılmaz. Bu kayıtlar genetik olarak yabani kuşları şehirde serbest yaşayan güvercinlerden ayırmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Kaya güvercini gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'yeterli kaydı olan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('columba-palumbus', 3048, 'record-summary', 1);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('columba-palumbus', 'ka', 'სად არის ქედანი დაფიქსირებული საქართველოში', 'რუკა საქართველოში iNaturalist-ის საჯარო, ფოტოდადასტურებულ დაკვირვებებს ეყრდნობა. რეგიონი რუკაზე გამოიკვეთება, თუ მასში სულ მცირე ერთი შენარჩუნებული ჩანაწერია. წერტილები და გამოკვეთილი რეგიონები არსებობის მტკიცებულებაა და არა მთელ რეგიონში უწყვეტი გავრცელება. ზოგი საჯარო კოორდინატი მიახლოებითია. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'ქედანის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('columba-palumbus', 'en', 'Common woodpigeon: where it is recorded in Georgia', 'This map uses public, photo-backed iNaturalist observations in Georgia. A region with at least one retained record is shaded on the map. Points and shading show evidence of occurrence, not continuous presence across a region. Some public coordinates are approximate. Record counts reflect observation effort, not population density.', 'Common woodpigeon observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('columba-palumbus', 'ru', 'Где вяхирь отмечен в Грузии', 'Карта использует публичные наблюдения iNaturalist с фотографиями из Грузии. Регион выделяется на карте при наличии не менее одной сохранённой записи. Точки и выделение показывают свидетельства присутствия, а не сплошное распространение по региону. Некоторые публичные координаты приблизительны. Число записей отражает усилия наблюдателей, а не плотность популяции.', 'Наблюдения вяхиря и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('columba-palumbus', 'tr', 'Tahtalı Gürcistan''da nerede kaydedildi?', 'Harita, Gürcistan''daki fotoğraflı halka açık iNaturalist gözlemlerini kullanır. En az bir tutulan kaydı olan bölge haritada vurgulanır. Noktalar ve vurgular, bölgenin tamamında kesintisiz yayılışı değil, varlık kanıtını gösterir. Bazı açık koordinatlar yaklaşıktır. Kayıt sayısı popülasyon yoğunluğunu değil gözlem çabasını yansıtır.', 'Tahtalı gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('coronella-austriaca', 26904, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('coronella-austriaca', 'ka', 'სად არის სპილენძა დაფიქსირებული საქართველოში', 'სპილენძას რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან და რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოყოფილი.', 'სპილენძას გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('coronella-austriaca', 'en', 'Smooth snake: where it is recorded in Georgia', 'The smooth snake map combines Reptiles.ge editorial photo records with public iNaturalist observations. Regions are taken from the records-by-region table, and only regions with enough records are shaded on the map.', 'Smooth snake distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('coronella-austriaca', 'ru', 'Где медянка отмечена в Грузии', 'Карта медянки объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам; на карте выделены только регионы с достаточным числом записей.', 'Данные о распространении медянки и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('coronella-austriaca', 'tr', 'Avusturya yılanı Gürcistan''da nerede kaydedildi?', 'Avusturya yılanı haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; haritada yalnızca yeterli kaydı olan bölgeler gölgelendirilir.', 'Avusturya yılanının Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('coturnix-coturnix', 804, 'record-summary', 1);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('coturnix-coturnix', 'ka', 'სად არის მწყერი დაფიქსირებული საქართველოში', 'მწყრის რუკა იყენებს iNaturalist-ის საჯარო დაკვირვებებს საქართველოდან. რეგიონები აღებულია ქვემოთ მოცემული ჩანაწერების ცხრილიდან; ამ სახეობისთვის ერთი ჩანაწერიც საკმარისია, რომ რეგიონი რუკაზე გამოიყოს. რეგიონული პოლიგონების გარეთ დარჩენილი წერტილები საერთო რაოდენობაში შედის, მაგრამ რეგიონს არ მიეკუთვნება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობასაც ასახავს და პოპულაციის სიმჭიდროვეს არ ზომავს.', 'მწყრის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('coturnix-coturnix', 'en', 'Common Quail: where it is recorded in Georgia', 'The Common Quail map uses public iNaturalist observations from Georgia. Regions come from the records-by-region table; for this species, a region with at least one record is shaded on the map. Points outside the regional polygons remain in the total without being assigned to a region. Record counts reflect observation effort, not population density.', 'Common Quail observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('coturnix-coturnix', 'ru', 'Где перепел отмечен в Грузии', 'Карта перепела использует публичные наблюдения iNaturalist из Грузии. Регионы взяты из таблицы записей; для этого вида одной записи достаточно, чтобы регион был выделен на карте. Точки вне региональных полигонов включены в общее число, но не отнесены к региону. Число записей отражает также активность наблюдателей, а не плотность популяции.', 'Наблюдения перепела и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('coturnix-coturnix', 'tr', 'Bıldırcın Gürcistan''da nerede kaydedildi?', 'Bıldırcın haritası Gürcistan''daki herkese açık iNaturalist gözlemlerini kullanır. Bölgeler kayıt tablosundan alınır; bu tür için tek bir kayıt, bölgenin haritada gölgelendirilmesi için yeterlidir. Bölge poligonlarının dışındaki noktalar genel toplama dahildir, ancak bir bölgeye atanmaz. Kayıt sayısı gözlem çabasını da yansıtır, nüfus yoğunluğunu ölçmez.', 'Bıldırcın gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('cuculus-canorus', 1907, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('cuculus-canorus', 'ka', 'სად არის გუგული დაფიქსირებული საქართველოში', 'გუგულის რუკა ეყრდნობა iNaturalist-ის საჯარო ფოტოდაკვირვებებს საქართველოდან. რუკაზე მონიშნულია მხოლოდ ის რეგიონები, რომლებსაც ჩანაწერების რეგიონულ ცხრილში საკმარისი ჩანაწერი აქვს; დანარჩენი წერტილები ცალკეული ჩანაწერებია. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'გუგულის საველე ჩანაწერები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('cuculus-canorus', 'en', 'Where the common cuckoo is recorded in Georgia', 'The cuckoo map uses public iNaturalist photo observations from Georgia. Only regions with enough records in the records-by-region table are shaded on the map; other points are individual records. Record counts reflect observation effort, not population density.', 'Common cuckoo field records and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('cuculus-canorus', 'ru', 'Где обыкновенная кукушка отмечена в Грузии', 'Карта кукушки основана на публичных фотонаблюдениях iNaturalist из Грузии. На карте закрашены только регионы с достаточным числом записей в таблице записей по регионам; остальные точки — отдельные записи. Число записей отражает интенсивность наблюдений, а не плотность популяции.', 'Полевые записи обыкновенной кукушки и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('cuculus-canorus', 'tr', 'Guguk kuşu Gürcistan''da nerede kaydedildi?', 'Guguk kuşu haritası Gürcistan''dan herkese açık iNaturalist fotoğraflı gözlemlerine dayanır. Haritada yalnızca bölgelere göre kayıt tablosunda yeterli kaydı olan bölgeler gösterilir; diğer noktalar tekil kayıtlardır. Kayıt sayısı popülasyon yoğunluğunu değil, gözlem yoğunluğunu yansıtır.', 'Guguk kuşunun Gürcistan haritasında arazi kayıtları ve kayıt bulunan bölgeler', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('darevskia-adjarica', 1403134, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-adjarica', 'ka', 'სად არის აჭარული კლდის ხვლიკი დაფიქსირებული საქართველოში', 'აჭარული კლდის ხვლიკის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და საქართველოში გაკეთებულ iNaturalist-ის საჯარო ფოტოდაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: ხუთი ან მეტი ჩანაწერის მქონე რეგიონი რუკაზე მონიშნულია; ნაკლები ჩანაწერის მქონე რეგიონს „ჩანაწერები ცოტაა“ სტატუსი აქვს. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'აჭარული კლდის ხვლიკის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი საკმარისი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-adjarica', 'en', 'Ajarian rock lizard: where it is recorded in Georgia', 'The Ajarian rock lizard map combines Reptiles.ge editorial photo records with public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: a region with five or more records is shaded on the map; a region with fewer records is marked as having too few records. Record counts reflect observation effort, not population density.', 'Ajarian rock lizard observations and regions with records on a map of Georgia', 'Region with records', 'regions with enough records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-adjarica', 'ru', 'Где аджарская скальная ящерица отмечена в Грузии', 'Карта аджарской скальной ящерицы объединяет редакционные фотозаписи Reptiles.ge и публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: регион с пятью и более записями закрашен на карте; при меньшем числе у региона статус «Мало записей». Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения аджарской скальной ящерицы и регионы с записями на карте Грузии', 'Регион с записями', 'региона с достаточным числом записей', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-adjarica', 'tr', 'Acar kayalık kertenkelesi Gürcistan''da nerede kaydedildi?', 'Acar kayalık kertenkelesi haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır: beş veya daha fazla kaydı olan bölge haritada gösterilir; daha az kaydı olan bölge “Kayıt az” olarak işaretlenir. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Acar kayalık kertenkelesi gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'yeterli kaydı olan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('darevskia-armeniaca', 35390, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-armeniaca', 'ka', 'სად არის სომხური კლდის ხვლიკი დაფიქსირებული საქართველოში', 'სომხური კლდის ხვლიკის რუკაზე ნაჩვენებია iNaturalist-ის საჯარო ფოტოდაკვირვებები საქართველოში. ზოგი დამკვირვებელი კოორდინატს დაახლოებით 28 კმ-ით ფარავს; ასეთი წერტილი მიახლოებითია და რეგიონის სტატუსში არ ითვლება. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მონიშნულია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები; დანარჩენი რეგიონები მონიშნული არ არის. Darevskia-ს სახეობები ერთმანეთს ჰგვანან, ამიტომ ცალკეული დაკვირვება დადასტურებული ამოცნობა არ არის. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'სომხური კლდის ხვლიკის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-armeniaca', 'en', 'Armenian rock lizard: where it is recorded in Georgia', 'The Armenian rock lizard map shows public iNaturalist photo observations in Georgia. Some observers obscure their coordinates by about 28 km; those points are approximate and do not count toward a region''s status. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions are not shaded. Darevskia species look alike, so a single observation is not a confirmed identification. Record counts reflect observation effort, not population density.', 'Armenian rock lizard observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-armeniaca', 'ru', 'Где армянская скальная ящерица отмечена в Грузии', 'На карте армянской скальной ящерицы показаны публичные фотонаблюдения iNaturalist в Грузии. Некоторые наблюдатели скрывают координаты примерно на 28 км; такие точки приблизительны и не учитываются в статусе региона. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей; остальные регионы не закрашены. Виды Darevskia похожи друг на друга, поэтому отдельное наблюдение не является подтверждённым определением. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения армянской скальной ящерицы и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-armeniaca', 'tr', 'Ermeni kayalık kertenkelesi Gürcistan''da nerede kaydedildi?', 'Ermeni kayalık kertenkelesi haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini gösterir. Bazı gözlemciler koordinatlarını yaklaşık 28 km gizler; bu noktalar yaklaşıktır ve bölgenin durumuna sayılmaz. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler gösterilir; diğer bölgeler gösterilmez. Darevskia türleri birbirine benzer, bu yüzden tek bir gözlem doğrulanmış bir teşhis değildir. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Ermeni kayalık kertenkelesi gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('darevskia-caucasica', 73750, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-caucasica', 'ka', 'სად არის კავკასიონის ხვლიკი დაფიქსირებული საქართველოში', 'კავკასიონის ხვლიკის რუკა საქართველოს iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მონიშნულია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები; დანარჩენი რეგიონები მონიშნული არ არის. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'კავკასიონის ხვლიკის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-caucasica', 'en', 'Caucasian rock lizard: where it is recorded in Georgia', 'The Caucasian rock lizard map uses public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions are not shaded. Record counts reflect observation effort, not population density.', 'Caucasian rock lizard observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-caucasica', 'ru', 'Где кавказская скальная ящерица отмечена в Грузии', 'Карта кавказской скальной ящерицы использует публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей; остальные регионы не закрашены. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения кавказской скальной ящерицы и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-caucasica', 'tr', 'Kafkas kayalık kertenkelesi Gürcistan''da nerede kaydedildi?', 'Kafkas kayalık kertenkelesi haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler gösterilir; diğer bölgeler gösterilmez. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Kafkas kayalık kertenkelesi gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('darevskia-clarkorum', 35388, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-clarkorum', 'ka', 'სად არის თურქული ხვლიკი დაფიქსირებული საქართველოში', 'თურქული ხვლიკის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებს, Georgian Biodiversity Database-ის ლოკალიტეტებს ჭარნალის მიდამოებიდან და საქართველოში გაკეთებულ iNaturalist-ის საჯარო ფოტოდაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: ხუთი ან მეტი ჩანაწერის მქონე რეგიონი რუკაზე მონიშნულია; ნაკლები ჩანაწერის მქონე რეგიონს „ჩანაწერები ცოტაა“ სტატუსი აქვს. iNaturalist ამ სახეობის ზუსტ ადგილს მალავს, ამიტომ მისი წერტილები მხოლოდ მიახლოებით არეალს აჩვენებს. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'თურქული ხვლიკის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი საკმარისი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-clarkorum', 'en', 'Clark''s rock lizard: where it is recorded in Georgia', 'The Clark''s rock lizard map combines Reptiles.ge editorial photo records, Georgian Biodiversity Database localities from the Charnali area, and public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: a region with five or more records is shaded on the map; a region with fewer records is marked as having too few records. iNaturalist hides the exact position of this species, so its points show only an approximate area. Record counts reflect observation effort, not population density.', 'Clark''s rock lizard observations and regions with records on a map of Georgia', 'Region with records', 'regions with enough records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-clarkorum', 'ru', 'Где ящерица Кларка отмечена в Грузии', 'Карта ящерицы Кларка объединяет редакционные фотозаписи Reptiles.ge, локалитеты Georgian Biodiversity Database из окрестностей Чарнали и публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: регион с пятью и более записями закрашен на карте; при меньшем числе у региона статус «Мало записей». iNaturalist скрывает точное место находки этого вида, поэтому его точки показывают лишь примерный участок. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения ящерицы Кларка и регионы с записями на карте Грузии', 'Регион с записями', 'региона с достаточным числом записей', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-clarkorum', 'tr', 'Clark kayalık kertenkelesi Gürcistan''da nerede kaydedildi?', 'Clark kayalık kertenkelesi haritası Reptiles.ge editoryal fotoğraf kayıtlarını, Charnali çevresinden Georgian Biodiversity Database lokalitelerini ve Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır: beş veya daha fazla kaydı olan bölge haritada gösterilir; daha az kaydı olan bölge “Kayıt az” olarak işaretlenir. iNaturalist bu türün tam konumunu gizler, bu yüzden oradaki noktalar yalnızca yaklaşık bir alanı gösterir. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Clark kayalık kertenkelesi gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'yeterli kaydı olan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('darevskia-daghestanica', 35389, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-daghestanica', 'ka', 'სად არის დაღესტნური ხვლიკი დაფიქსირებული საქართველოში', 'დაღესტნური ხვლიკის რუკა აერთიანებს საქართველოს საველე ლოკალიტეტებსა და iNaturalist-ის საჯარო ფოტოდაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: ხუთი ან მეტი ჩანაწერის მქონე რეგიონი რუკაზე მონიშნულია; ნაკლები ჩანაწერის მქონე რეგიონს „ჩანაწერები ცოტაა“ სტატუსი აქვს. iNaturalist-ის დაკვირვებები, რომელთა ამოცნობა ჯერ დადასტურებული არ არის, რუკაზე ჩანს, მაგრამ არ ითვლება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'დაღესტნური ხვლიკის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი საკმარისი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-daghestanica', 'en', 'Daghestanian Rock Lizard: where it is recorded in Georgia', 'The Daghestanian Rock Lizard map combines field localities from Georgia with public iNaturalist photo observations. Regions come from the records-by-region table: a region with five or more records is shaded on the map; a region with fewer records is marked as having too few records. iNaturalist observations that still need an ID are shown but not counted. Record counts reflect observation effort, not population density.', 'Daghestanian Rock Lizard observations and regions with records on a map of Georgia', 'Region with records', 'regions with enough records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-daghestanica', 'ru', 'Где дагестанская скальная ящерица отмечена в Грузии', 'Карта дагестанской скальной ящерицы объединяет полевые локалитеты из Грузии и публичные фотонаблюдения iNaturalist. Регионы взяты из таблицы записей: регион с пятью и более записями закрашен на карте; при меньшем числе у региона статус «Мало записей». Наблюдения iNaturalist, которым ещё нужно подтверждение определения, показаны, но не учитываются. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения дагестанской скальной ящерицы и регионы с записями на карте Грузии', 'Регион с записями', 'региона с достаточным числом записей', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-daghestanica', 'tr', 'Dağıstan kayalık kertenkelesi Gürcistan''da nerede kaydedildi?', 'Dağıstan kayalık kertenkelesi haritası Gürcistan''daki arazi lokalitelerini ve herkese açık iNaturalist fotoğraflı gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır: beş veya daha fazla kaydı olan bölge haritada gösterilir; daha az kaydı olan bölge “Kayıt az” olarak işaretlenir. Tür teşhisi henüz doğrulanmamış iNaturalist gözlemleri gösterilir ama sayılmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Dağıstan kayalık kertenkelesi gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'yeterli kaydı olan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('darevskia-dahli', 73752, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-dahli', 'ka', 'სად არის დალის ხვლიკი დაფიქსირებული საქართველოში', 'დალის ხვლიკის რუკა ზუსტ ლოკალიტეტებსა და iNaturalist-ის საჯარო ფოტოდაკვირვებებს აერთიანებს. ეს საჯარო კოორდინატები დაახლოებით 28 კმ-ითაა დაფარული, ამიტომ საზღვართან მდებარე წერტილი მიახლოებითია. ზუსტი ლოკალიტეტები რეგიონის ჩანაწერებში ითვლება. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მონიშნულია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები; დანარჩენი რეგიონები მონიშნული არ არის. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'დალის ხვლიკის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-dahli', 'en', 'Dahl''s rock lizard: where it is recorded in Georgia', 'The Dahl''s rock lizard map combines precise localities with public iNaturalist photo observations in Georgia. Those public coordinates are obscured by about 28 km, so a point near a regional border is approximate. Precise localities count toward a region''s records. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions are not shaded. Record counts reflect observation effort, not population density.', 'Dahl''s rock lizard observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-dahli', 'ru', 'Где ящерица Даля отмечена в Грузии', 'Карта ящерицы Даля объединяет точные локалитеты и публичные фотонаблюдения iNaturalist в Грузии. Эти публичные координаты скрыты примерно на 28 км, поэтому точка у границы региона приблизительна. Точные локалитеты учитываются в записях региона. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей; остальные регионы не закрашены. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения ящерицы Даля и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-dahli', 'tr', 'Dahl kayalık kertenkelesi Gürcistan''da nerede kaydedildi?', 'Dahl kayalık kertenkelesi haritası kesin lokaliteleri Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemleriyle birleştirir. Bu açık koordinatlar yaklaşık 28 km gizlenmiştir, bu yüzden sınıra yakın bir nokta yaklaşıktır. Kesin lokaliteler bölgenin kayıtlarına sayılır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler gösterilir; diğer bölgeler gösterilmez. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Dahl kayalık kertenkelesi gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('darevskia-derjugini', 35387, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-derjugini', 'ka', 'სად არის ართვინის ხვლიკი დაფიქსირებული საქართველოში', 'ართვინის ხვლიკის რუკა საქართველოს iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. ეს საჯარო კოორდინატები დაახლოებით 28 კმ-ითაა დაფარული, ამიტომ საზღვართან მდებარე წერტილი მიახლოებითია. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: ხუთი ან მეტი ჩანაწერის მქონე რეგიონი რუკაზე მონიშნულია; ნაკლები ჩანაწერის მქონე რეგიონს „ჩანაწერები ცოტაა“ სტატუსი აქვს. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'ართვინის ხვლიკის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი საკმარისი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-derjugini', 'en', 'Artvin lizard: where it is recorded in Georgia', 'The Artvin lizard map uses public iNaturalist photo observations in Georgia. Those public coordinates are obscured by about 28 km, so a point near a regional border is approximate. Regions come from the records-by-region table: a region with five or more records is shaded on the map; a region with fewer records is marked as having too few records. Record counts reflect observation effort, not population density.', 'Artvin lizard observations and regions with records on a map of Georgia', 'Region with records', 'regions with enough records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-derjugini', 'ru', 'Где артвинская ящерица отмечена в Грузии', 'Карта артвинской ящерицы использует публичные фотонаблюдения iNaturalist в Грузии. Эти публичные координаты скрыты примерно на 28 км, поэтому точка у границы региона приблизительна. Регионы взяты из таблицы записей: регион с пятью и более записями закрашен на карте; при меньшем числе у региона статус «Мало записей». Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения артвинской ящерицы и регионы с записями на карте Грузии', 'Регион с записями', 'региона с достаточным числом записей', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-derjugini', 'tr', 'Artvin kertenkelesi Gürcistan''da nerede kaydedildi?', 'Artvin kertenkelesi haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bu açık koordinatlar yaklaşık 28 km gizlenmiştir, bu yüzden bölge sınırına yakın bir nokta yaklaşıktır. Bölgeler, bölgelere göre kayıt tablosundan alınır: beş veya daha fazla kaydı olan bölge haritada gösterilir; daha az kaydı olan bölge “Kayıt az” olarak işaretlenir. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Artvin kertenkelesi gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'yeterli kaydı olan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('darevskia-mixta', 35386, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-mixta', 'ka', 'სად არის აჭარული ხვლიკი დაფიქსირებული საქართველოში', 'აჭარული ხვლიკის რუკა აერთიანებს საქართველოს საველე ლოკალიტეტებსა და iNaturalist-ის საჯარო ფოტოდაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: ხუთი ან მეტი ჩანაწერის მქონე რეგიონი რუკაზე მონიშნულია; ნაკლები ჩანაწერის მქონე რეგიონს „ჩანაწერები ცოტაა“ სტატუსი აქვს. iNaturalist-ის დაკვირვებები, რომელთა ამოცნობა ჯერ დადასტურებული არ არის, რუკაზე ჩანს, მაგრამ არ ითვლება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'აჭარული ხვლიკის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი საკმარისი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-mixta', 'en', 'Mixed rock lizard: where it is recorded in Georgia', 'The mixed rock lizard map combines field localities from Georgia with public iNaturalist photo observations. Regions come from the records-by-region table: a region with five or more records is shaded on the map; a region with fewer records is marked as having too few records. iNaturalist observations that still need an ID are shown but not counted. Record counts reflect observation effort, not population density.', 'Mixed rock lizard observations and regions with records on a map of Georgia', 'Region with records', 'regions with enough records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-mixta', 'ru', 'Где смешанная скальная ящерица отмечена в Грузии', 'Карта смешанной скальной ящерицы объединяет полевые локалитеты из Грузии и публичные фотонаблюдения iNaturalist. Регионы взяты из таблицы записей: регион с пятью и более записями закрашен на карте; при меньшем числе у региона статус «Мало записей». Наблюдения iNaturalist, которым ещё нужно подтверждение определения, показаны, но не учитываются. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения смешанной скальной ящерицы и регионы с записями на карте Грузии', 'Регион с записями', 'региона с достаточным числом записей', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-mixta', 'tr', 'Karışık kayalık kertenkele Gürcistan''da nerede kaydedildi?', 'Karışık kayalık kertenkele haritası Gürcistan''daki arazi lokalitelerini ve herkese açık iNaturalist fotoğraflı gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır: beş veya daha fazla kaydı olan bölge haritada gösterilir; daha az kaydı olan bölge “Kayıt az” olarak işaretlenir. Tür teşhisi henüz doğrulanmamış iNaturalist gözlemleri gösterilir ama sayılmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Karışık kayalık kertenkele gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'yeterli kaydı olan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('darevskia-obscura', 35376, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-obscura', 'ka', 'სად არის მესხური კლდის ხვლიკი დაფიქსირებული საქართველოში', 'მესხური კლდის ხვლიკის რუკა აერთიანებს საქართველოს iNaturalist-ის საჯარო დაკვირვებებს, რომლებიც Darevskia rudis obscura-ს სახელითაა შეტანილი, და აღმწერის გარეშე დამატებულ ლოკალიტეტებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მონიშნულია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები; დანარჩენი რეგიონები მონიშნული არ არის. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'მესხური კლდის ხვლიკის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-obscura', 'en', 'Obscure rock lizard: where it is recorded in Georgia', 'The obscure rock lizard map combines public iNaturalist observations in Georgia filed as Darevskia rudis obscura with localities that have no observer. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions are not shaded. Record counts reflect observation effort, not population density.', 'Obscure rock lizard observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-obscura', 'ru', 'Где тёмная скальная ящерица отмечена в Грузии', 'Карта тёмной скальной ящерицы объединяет публичные наблюдения iNaturalist в Грузии, внесённые как Darevskia rudis obscura, и локалитеты без наблюдателя. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей; остальные регионы не закрашены. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения тёмной скальной ящерицы и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-obscura', 'tr', 'Koyu kayalık kertenkele Gürcistan''da nerede kaydedildi?', 'Koyu kayalık kertenkele haritası, Gürcistan''da Darevskia rudis obscura adıyla girilmiş herkese açık iNaturalist gözlemlerini ve gözlemcisi olmayan lokaliteleri birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler gösterilir; diğer bölgeler gösterilmez. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Koyu kayalık kertenkele gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('darevskia-portschinskii', 35384, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-portschinskii', 'ka', 'სად არის მტკვრის ხვლიკი დაფიქსირებული საქართველოში', 'მტკვრის ხვლიკის რუკა ატლასის საველე ფოტოებსა და საქართველოში გაკეთებულ iNaturalist-ის საჯარო დაკვირვებებს აერთიანებს. ჩანაწერების რეგიონული ცხრილი დაკვირვებებსა და დადასტურებულ გავრცელებას განასხვავებს: რუკაზე მხოლოდ დადასტურებული სტატუსის მქონე რეგიონი გამოიკვეთება. რეგიონი, სადაც მხოლოდ რამდენიმე ჩანაწერია, ცხრილში ჩანს, მაგრამ გავრცელებად არ ითვლება. iNaturalist-ის მიერ დაფარული კოორდინატი და ამოუცნობი დაკვირვება ამ სტატუსში არ ითვლება. ცალკეული წერტილები დაკვირვების ადგილებს აჩვენებს და არა პოპულაციის სიმჭიდროვეს.', 'მტკვრის ხვლიკის დაკვირვებები და დადასტურებული რეგიონები საქართველოს რუკაზე', 'დადასტურებული რეგიონი', NULL, 'დადასტურებული გავრცელება');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-portschinskii', 'en', 'Portschinsky''s lizard: where it is recorded in Georgia', 'The Portschinsky''s lizard map combines atlas field photos with public iNaturalist observations in Georgia. The records-by-region table keeps observations separate from confirmed range: only a region with a confirmed status is shaded. A region with only a few records is listed but not counted as range. iNaturalist coordinates that are obscured and observations still awaiting identification do not count toward that status. Individual points show observation locations, not population density.', 'Portschinsky''s lizard observations and confirmed regions on a map of Georgia', 'Confirmed region', NULL, 'Confirmed distribution');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-portschinskii', 'ru', 'Где куринская ящерица отмечена в Грузии', 'Карта куринской ящерицы объединяет полевые фото атласа и публичные наблюдения iNaturalist в Грузии. Таблица записей по регионам отделяет наблюдения от подтверждённого ареала: на карте выделяются только регионы с подтверждённым статусом. Регион, где записей всего несколько, указан в таблице, но не считается частью ареала. Скрытые iNaturalist координаты и наблюдения, ожидающие определения, не учитываются для этого статуса. Отдельные точки показывают места наблюдений, а не плотность популяции.', 'Наблюдения куринской ящерицы и подтверждённые регионы на карте Грузии', 'Подтверждённый регион', NULL, 'Подтверждённое распространение');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-portschinskii', 'tr', 'Kura kertenkelesi Gürcistan''da nerede kaydedildi?', 'Kura kertenkelesi haritası atlasın arazi fotoğraflarını ve Gürcistan''daki herkese açık iNaturalist gözlemlerini birleştirir. Bölgelere göre kayıt tablosu gözlemleri doğrulanmış yayılıştan ayırır: haritada yalnızca doğrulanmış durumundaki bölge taranır. Yalnızca birkaç kaydı olan bölge tabloda görünür, ancak yayılış sayılmaz. iNaturalist''in gizlediği koordinatlar ve henüz tanımlanmamış gözlemler bu duruma sayılmaz. Tekil noktalar gözlem yerlerini gösterir, nüfus yoğunluğunu değil.', 'Kura kertenkelesi gözlemleri ve doğrulanmış bölgeler Gürcistan haritasında', 'Doğrulanmış bölge', NULL, 'Doğrulanmış yayılış');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('darevskia-praticola', 35383, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-praticola', 'ka', 'სად არის მდელოს ხვლიკი დაფიქსირებული საქართველოში', 'მდელოს ხვლიკის რუკა საქართველოში გაკეთებულ iNaturalist-ის საჯარო დაკვირვებებს ეყრდნობა. ჩანაწერების რეგიონული ცხრილი დაკვირვებებსა და დადასტურებულ გავრცელებას განასხვავებს: რუკაზე მხოლოდ დადასტურებული სტატუსის მქონე რეგიონი გამოიკვეთება. iNaturalist ამ სახეობის ყველა საჯარო კოორდინატს დაახლოებით 28 კმ-ით ფარავს, დაფარული კოორდინატი კი ამ სტატუსში არ ითვლება, ამიტომ რუკაზე ჯერ არცერთი რეგიონი არ არის გამოკვეთილი. iNaturalist კოლხურ მდელოს ხვლიკს (D. pontica) მდელოს ხვლიკის ქვესახეობად განიხილავს, ამიტომ დასავლეთ საქართველოს ჩანაწერები შესაძლოა მას ეკუთვნოდეს. ცალკეული წერტილები დაკვირვების მიახლოებით ადგილებს აჩვენებს და არა პოპულაციის სიმჭიდროვეს.', 'მდელოს ხვლიკის დაკვირვებები და დადასტურებული რეგიონები საქართველოს რუკაზე', 'დადასტურებული რეგიონი', NULL, 'დადასტურებული გავრცელება');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-praticola', 'en', 'Meadow Lizard: where it is recorded in Georgia', 'The Meadow Lizard map uses public iNaturalist observations in Georgia. The records-by-region table keeps observations separate from confirmed range: only a region with a confirmed status is shaded. iNaturalist obscures every public coordinate for this species by about 28 km, and obscured coordinates do not count toward that status, so no region is shaded yet. iNaturalist treats the Pontic Meadow Lizard (D. pontica) as a subspecies of the Meadow Lizard, so records from western Georgia may belong to it. Individual points show approximate observation locations, not population density.', 'Meadow Lizard observations and confirmed regions on a map of Georgia', 'Confirmed region', NULL, 'Confirmed distribution');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-praticola', 'ru', 'Где луговая ящерица отмечена в Грузии', 'Карта луговой ящерицы основана на публичных наблюдениях iNaturalist в Грузии. Таблица записей по регионам отделяет наблюдения от подтверждённого ареала: на карте выделяются только регионы с подтверждённым статусом. iNaturalist скрывает все публичные координаты этого вида примерно на 28 км, а скрытые координаты для этого статуса не учитываются, поэтому пока ни один регион не выделен. iNaturalist рассматривает понтийскую луговую ящерицу (D. pontica) как подвид луговой ящерицы, поэтому записи из западной Грузии могут относиться к ней. Отдельные точки показывают приблизительные места наблюдений, а не плотность популяции.', 'Наблюдения луговой ящерицы и подтверждённые регионы на карте Грузии', 'Подтверждённый регион', NULL, 'Подтверждённое распространение');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-praticola', 'tr', 'Çayır kertenkelesi Gürcistan''da nerede kaydedildi?', 'Çayır kertenkelesi haritası Gürcistan''daki herkese açık iNaturalist gözlemlerine dayanır. Bölgelere göre kayıt tablosu gözlemleri doğrulanmış yayılıştan ayırır: haritada yalnızca doğrulanmış durumundaki bölge taranır. iNaturalist bu türün tüm açık koordinatlarını yaklaşık 28 km gizler ve gizli koordinatlar bu duruma sayılmaz; bu yüzden henüz hiçbir bölge taranmamıştır. iNaturalist Pontik çayır kertenkelesini (D. pontica) çayır kertenkelesinin alt türü olarak ele alır; bu nedenle batı Gürcistan''dan gelen kayıtlar ona ait olabilir. Tekil noktalar yaklaşık gözlem yerlerini gösterir, nüfus yoğunluğunu değil.', 'Çayır kertenkelesi gözlemleri ve doğrulanmış bölgeler Gürcistan haritasında', 'Doğrulanmış bölge', NULL, 'Doğrulanmış yayılış');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('darevskia-valentini', 35362, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-valentini', 'ka', 'სად არის ვალენტინის ხვლიკი დაფიქსირებული საქართველოში', 'ვალენტინის ხვლიკის რუკა აერთიანებს ატლასისთვის მოწოდებულ საველე ჩანაწერებსა და საქართველოში გაკეთებულ iNaturalist-ის საჯარო დაკვირვებებს. ჩანაწერების რეგიონული ცხრილი დაკვირვებებსა და დადასტურებულ გავრცელებას განასხვავებს: რუკაზე მხოლოდ დადასტურებული სტატუსის მქონე რეგიონი გამოიკვეთება. iNaturalist-ის მიერ დაფარული კოორდინატი და ამოუცნობი დაკვირვება ამ სტატუსში არ ითვლება. ცალკეული წერტილები დაკვირვების ადგილებს აჩვენებს და არა პოპულაციის სიმჭიდროვეს.', 'ვალენტინის ხვლიკის დაკვირვებები და დადასტურებული რეგიონები საქართველოს რუკაზე', 'დადასტურებული რეგიონი', NULL, 'დადასტურებული გავრცელება');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-valentini', 'en', 'Valentin''s lizard: where it is recorded in Georgia', 'The Valentin''s lizard map combines field records supplied for the atlas with public iNaturalist observations in Georgia. The records-by-region table keeps observations separate from confirmed range: only a region with a confirmed status is shaded. iNaturalist coordinates that are obscured and observations still awaiting identification do not count toward that status. Individual points show observation locations, not population density.', 'Valentin''s lizard observations and confirmed regions on a map of Georgia', 'Confirmed region', NULL, 'Confirmed distribution');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-valentini', 'ru', 'Где ящерица Валентина отмечена в Грузии', 'Карта ящерицы Валентина объединяет полевые записи, предоставленные для атласа, и публичные наблюдения iNaturalist в Грузии. Таблица записей по регионам отделяет наблюдения от подтверждённого ареала: на карте выделяются только регионы с подтверждённым статусом. Скрытые iNaturalist координаты и наблюдения, ожидающие определения, не учитываются для этого статуса. Отдельные точки показывают места наблюдений, а не плотность популяции.', 'Наблюдения ящерицы Валентина и подтверждённые регионы на карте Грузии', 'Подтверждённый регион', NULL, 'Подтверждённое распространение');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('darevskia-valentini', 'tr', 'Valentin kertenkelesi Gürcistan''da nerede kaydedildi?', 'Valentin kertenkelesi haritası atlas için sağlanan arazi kayıtlarını ve Gürcistan''daki herkese açık iNaturalist gözlemlerini birleştirir. Bölgelere göre kayıt tablosu gözlemleri doğrulanmış yayılıştan ayırır: haritada yalnızca doğrulanmış durumundaki bölge taranır. iNaturalist''in gizlediği koordinatlar ve henüz tanımlanmamış gözlemler bu duruma sayılmaz. Tekil noktalar gözlem yerlerini gösterir, nüfus yoğunluğunu değil.', 'Valentin kertenkelesi gözlemleri ve doğrulanmış bölgeler Gürcistan haritasında', 'Doğrulanmış bölge', NULL, 'Doğrulanmış yayılış');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('dendrocopos-major', 17871, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('dendrocopos-major', 'ka', 'სად არის დიდი ჭრელი კოდალა დაფიქსირებული საქართველოში', 'დიდი ჭრელი კოდალას რუკა საქართველოს iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მონიშნულია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები; დანარჩენი რეგიონები მონიშნული არ არის. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'დიდი ჭრელი კოდალას დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('dendrocopos-major', 'en', 'Great spotted woodpecker: where it is recorded in Georgia', 'The great spotted woodpecker map uses public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions are not shaded. Record counts reflect observation effort, not population density.', 'Great spotted woodpecker observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('dendrocopos-major', 'ru', 'Где большой пёстрый дятел отмечен в Грузии', 'Карта большого пёстрого дятла использует публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей; остальные регионы не закрашены. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения большого пёстрого дятла и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('dendrocopos-major', 'tr', 'Orman alaca ağaçkakanı Gürcistan''da nerede kaydedildi?', 'Orman alaca ağaçkakanı haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler gösterilir; diğer bölgeler gösterilmez. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Orman alaca ağaçkakanı gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('dolichophis-schmidti', 73760, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('dolichophis-schmidti', 'ka', 'სად არის წითელმუცელა მცურავი დაფიქსირებული საქართველოში', 'წითელმუცელა მცურავის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებს, ხელით დამუშავებულ ლოკალიტეტებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან და რუკაზე მონიშნულია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები.', 'წითელმუცელა მცურავის გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('dolichophis-schmidti', 'en', 'Red-bellied racer: where it is recorded in Georgia', 'The red-bellied racer map combines Reptiles.ge editorial photo records, hand-curated localities, and public iNaturalist observations. Regions are taken from the records-by-region table, and only regions with enough records are shaded on the map.', 'Red-bellied racer distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('dolichophis-schmidti', 'ru', 'Где краснобрюхий полоз отмечен в Грузии', 'Карта краснобрюхого полоза объединяет редакционные фотозаписи Reptiles.ge, вручную обработанные локалитеты и публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам; на карте закрашены только регионы с достаточным числом записей.', 'Данные о распространении краснобрюхого полоза и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('dolichophis-schmidti', 'tr', 'Kırmızı karınlı yılan Gürcistan''da nerede kaydedildi?', 'Kırmızı karınlı yılan haritası Reptiles.ge editoryal fotoğraf kayıtlarını, elle düzenlenmiş lokaliteleri ve herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; haritada yalnızca yeterli kaydı olan bölgeler gösterilir.', 'Kırmızı karınlı yılanın Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('eirenis-collaris', 30290, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('eirenis-collaris', 'ka', 'სად არის საყელოიანი ეირენისი დაფიქსირებული საქართველოში', 'საყელოიანი ეირენისის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს საქართველოში. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოკვეთილი; ცოტა ჩანაწერის მქონე რეგიონი არ გამოიკვეთება. დაფარული კოორდინატის მქონე ჩანაწერი რეგიონის სტატუსში არ ითვლება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'საყელოიანი ეირენისის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('eirenis-collaris', 'en', 'Collared dwarf snake: where it is recorded in Georgia', 'The collared dwarf snake map uses Reptiles.ge editorial photo records and public iNaturalist observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; a region with too few records is not shaded. Records with obscured coordinates do not count towards a region''s status. Record counts reflect observation effort, not population density.', 'Collared dwarf snake observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('eirenis-collaris', 'ru', 'Где ошейниковый эйренис отмечен в Грузии', 'Карта ошейникового эйрениса объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте выделены только регионы с достаточным числом записей; регион с малым числом записей не выделяется. Записи со скрытыми координатами не учитываются в статусе региона. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения ошейникового эйрениса и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('eirenis-collaris', 'tr', 'Yakalı cüce yılan Gürcistan''da nerede kaydedildi?', 'Yakalı cüce yılan haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve Gürcistan''daki herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler vurgulanır; kaydı az olan bölge vurgulanmaz. Koordinatı gizlenmiş kayıtlar bölgenin durumuna sayılmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Yakalı cüce yılan gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('eirenis-modestus', 30293, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('eirenis-modestus', 'ka', 'სად არის წყნარი ეირენისი დაფიქსირებული საქართველოში', 'წყნარი ეირენისის რუკა საქართველოს iNaturalist-ის საჯარო დაკვირვებებს ეყრდნობა. გამოკვეთილია მხოლოდ ის რეგიონები, რომლებსაც ჩანაწერების რეგიონულ ცხრილში საკმარისი ჩანაწერი აქვთ; ცალკეული ჩანაწერი მთელი რეგიონის გავრცელებას არ ნიშნავს. ზოგი საჯარო კოორდინატი დაფარული ან მიახლოებითია, ამიტომ საზღვართან რეგიონის მიკუთვნება გაურკვეველია. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'წყნარი ეირენისის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('eirenis-modestus', 'en', 'Ring-headed dwarf snake: where it is recorded in Georgia', 'The ring-headed dwarf snake map uses public iNaturalist observations in Georgia. Only regions with enough records in the records-by-region table are highlighted; isolated records do not establish region-wide distribution. Some public coordinates are obscured or approximate, making assignments near regional borders uncertain. Record counts reflect observation effort, not population density.', 'Ring-headed dwarf snake observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('eirenis-modestus', 'ru', 'Где скромный эйренис отмечен в Грузии', 'Карта скромного эйрениса основана на публичных наблюдениях iNaturalist в Грузии. Выделены только регионы с достаточным числом записей в таблице записей; отдельная запись не означает распространение по всему региону. Некоторые публичные координаты скрыты или приблизительны, поэтому привязка точек у границ регионов неопределённа. Число записей отражает активность наблюдателей, не плотность популяции.', 'Наблюдения скромного эйрениса и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('eirenis-modestus', 'tr', 'Halkalı başlı cüce yılan Gürcistan''da nerede kaydedildi?', 'Halkalı başlı cüce yılan haritası Gürcistan''daki herkese açık iNaturalist gözlemlerini kullanır. Yalnızca bölgesel kayıt tablosunda yeterli kaydı olan bölgeler vurgulanır; tek bir kayıt tüm bölgede yayılış anlamına gelmez. Bazı halka açık koordinatlar gizlenmiş veya yaklaşıktır; bölge sınırlarına yakın noktaların atanması belirsizdir. Kayıt sayısı gözlem çabasını yansıtır, popülasyon yoğunluğunu ölçmez.', 'Halkalı başlı cüce yılan gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('elaphe-urartica', 965955, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('elaphe-urartica', 'ka', 'სად არის ურარტუს მცურავი დაფიქსირებული საქართველოში', 'ურარტუს მცურავის რუკა საქართველოს iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მონიშნულია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები; დანარჩენი რეგიონები მონიშნული არ არის. ზოგი საჯარო კოორდინატი დაფარული ან მიახლოებითია, ამიტომ საზღვართან მდებარე წერტილი თავისთავად ახალ რეგიონს არ ამატებს. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'ურარტუს მცურავის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('elaphe-urartica', 'en', 'Urartian ratsnake: where it is recorded in Georgia', 'The Urartian ratsnake map uses public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions are not shaded. Some public coordinates are obscured or approximate, so a point near a border does not by itself add a new region. Record counts reflect observation effort, not population density.', 'Urartian ratsnake observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('elaphe-urartica', 'ru', 'Где урартский полоз отмечен в Грузии', 'Карта урартского полоза использует публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей; остальные регионы не закрашены. Часть публичных координат скрыта или приблизительна, поэтому точка у границы сама по себе не добавляет новый регион. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения урартского полоза и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('elaphe-urartica', 'tr', 'Urartu sıçanyılanı Gürcistan''da nerede kaydedildi?', 'Urartu sıçanyılanı haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler gösterilir; diğer bölgeler gösterilmez. Bazı halka açık koordinatlar gizlenmiş veya yaklaşıktır; sınırdaki bir nokta kendiliğinden yeni bir bölge eklemez. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Urartu sıçanyılanı gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('emys-orbicularis', 39867, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('emys-orbicularis', 'ka', 'სად არის ჭაობის კუ დაფიქსირებული საქართველოში', 'ჭაობის კუს რუკა აჩვენებს iNaturalist-ის საჯარო დაკვირვებებს საქართველოში. რუკაზე მხოლოდ ის რეგიონებია გამოკვეთილი, რომლებსაც ჩანაწერების ცხრილში საკმარისი ჩანაწერი აქვს. iNaturalist ამ სახეობის საჯარო კოორდინატებს ფარავს, ამიტომ წერტილები მიახლოებითია: ზოგი ზღვაში ან მეზობელ რეგიონში ხვდება, ხოლო რეგიონების საზღვრებს გარეთ მოხვედრილი წერტილები ცხრილში არ ითვლება. გამოკვეთილი რეგიონი არ ნიშნავს მის მთელ ტერიტორიაზე გავრცელებას; ჩანაწერების რაოდენობა პოპულაციის სიმჭიდროვეს არ ზომავს.', 'ჭაობის კუს საველე ჩანაწერები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('emys-orbicularis', 'en', 'Where European pond turtles are recorded in Georgia', 'The European pond turtle map shows public iNaturalist observations in Georgia. Only regions with enough records in the records table are shaded on the map. iNaturalist obscures the public coordinates of this species, so points are approximate, some fall offshore or across a border, and those outside the region outlines are not counted. A shaded region does not mean the turtle occupies all of it; record counts reflect observation effort, not population density.', 'European pond turtle field records and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('emys-orbicularis', 'ru', 'Где европейская болотная черепаха отмечена в Грузии', 'Карта европейской болотной черепахи показывает публичные наблюдения iNaturalist в Грузии. На карте выделены только регионы с достаточным числом записей в таблице записей. iNaturalist скрывает публичные координаты этого вида, поэтому точки приблизительны: некоторые попадают в море или в соседний регион, а точки за границами регионов в таблице не учитываются. Выделенный регион не означает присутствие на всей его территории; число записей не измеряет плотность популяции.', 'Полевые записи европейской болотной черепахи и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('emys-orbicularis', 'tr', 'Avrupa bataklık kaplumbağası Gürcistan''da nerede kaydedildi?', 'Avrupa bataklık kaplumbağası haritası Gürcistan''daki herkese açık iNaturalist gözlemlerini gösterir. Haritada yalnızca kayıt tablosunda yeterli kaydı olan bölgeler vurgulanır. iNaturalist bu türün açık koordinatlarını gizler; bu yüzden noktalar yaklaşıktır, bazıları denize veya komşu bölgeye düşer ve bölge sınırları dışında kalan noktalar tabloda sayılmaz. Vurgulanan bölge türün her yerinde bulunduğu anlamına gelmez; kayıt sayısı popülasyon yoğunluğunu ölçmez.', 'Avrupa bataklık kaplumbağasının arazi kayıtları ve kayıt bulunan bölgeleri Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('eremias-velox', 36012, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('eremias-velox', 'ka', 'სად არის მარდი ფსვენი დაფიქსირებული საქართველოში', 'მარდი ფსვენის რუკა აერთიანებს ატლასისთვის მოწოდებულ საველე ფოტოებსა და საქართველოში გაკეთებულ iNaturalist-ის საჯარო დაკვირვებებს. ჩანაწერების რეგიონული ცხრილი დაკვირვებებსა და დადასტურებულ გავრცელებას განასხვავებს: რუკაზე მხოლოდ დადასტურებული სტატუსის მქონე რეგიონი გამოიკვეთება. რეგიონი, სადაც მხოლოდ რამდენიმე ჩანაწერია, ცხრილში ჩანს, მაგრამ გავრცელებად არ ითვლება. iNaturalist-ის მიერ დაფარული კოორდინატი და ამოუცნობი დაკვირვება ამ სტატუსში არ ითვლება. ცალკეული წერტილები დაკვირვების ადგილებს აჩვენებს და არა პოპულაციის სიმჭიდროვეს.', 'მარდი ფსვენის დაკვირვებები და დადასტურებული რეგიონები საქართველოს რუკაზე', 'დადასტურებული რეგიონი', NULL, 'დადასტურებული გავრცელება');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('eremias-velox', 'en', 'Rapid racerunner: where it is recorded in Georgia', 'The rapid racerunner map combines field photos supplied for the atlas with public iNaturalist observations in Georgia. The records-by-region table keeps observations separate from confirmed range: only a region with a confirmed status is shaded. A region with only a few records is listed but not counted as range. iNaturalist coordinates that are obscured and observations still awaiting identification do not count toward that status. Individual points show observation locations, not population density.', 'Rapid racerunner observations and confirmed regions on a map of Georgia', 'Confirmed region', NULL, 'Confirmed distribution');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('eremias-velox', 'ru', 'Где быстрая ящурка отмечена в Грузии', 'Карта быстрой ящурки объединяет полевые фотографии, предоставленные для атласа, и публичные наблюдения iNaturalist в Грузии. Таблица записей по регионам отделяет наблюдения от подтверждённого ареала: на карте выделяются только регионы с подтверждённым статусом. Регион, где записей всего несколько, указан в таблице, но не считается частью ареала. Скрытые iNaturalist координаты и наблюдения, ожидающие определения, не учитываются для этого статуса. Отдельные точки показывают места наблюдений, а не плотность популяции.', 'Наблюдения быстрой ящурки и подтверждённые регионы на карте Грузии', 'Подтверждённый регион', NULL, 'Подтверждённое распространение');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('eremias-velox', 'tr', 'Hızlı koşar kertenkele Gürcistan''da nerede kaydedildi?', 'Hızlı koşar kertenkele haritası atlas için sağlanan arazi fotoğraflarını ve Gürcistan''daki herkese açık iNaturalist gözlemlerini birleştirir. Bölgelere göre kayıt tablosu gözlemleri doğrulanmış yayılıştan ayırır: haritada yalnızca doğrulanmış durumundaki bölge taranır. Yalnızca birkaç kaydı olan bölge tabloda görünür, ancak yayılış sayılmaz. iNaturalist''in gizlediği koordinatlar ve henüz tanımlanmamış gözlemler bu duruma sayılmaz. Tekil noktalar gözlem yerlerini gösterir, nüfus yoğunluğunu değil.', 'Hızlı koşar kertenkele gözlemleri ve doğrulanmış bölgeler Gürcistan haritasında', 'Doğrulanmış bölge', NULL, 'Doğrulanmış yayılış');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('erithacus-rubecula', 13094, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('erithacus-rubecula', 'ka', 'სად არის გულწითელა დაფიქსირებული საქართველოში', 'გულწითელას რუკა საქართველოს iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მონიშნულია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები; დანარჩენი რეგიონები მონიშნული არ არის. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'გულწითელას დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('erithacus-rubecula', 'en', 'European robin: where it is recorded in Georgia', 'The European robin map uses public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions are not shaded. Record counts reflect observation effort, not population density.', 'European robin observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('erithacus-rubecula', 'ru', 'Где зарянка отмечена в Грузии', 'Карта зарянки использует публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей; остальные регионы не закрашены. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения зарянки и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('erithacus-rubecula', 'tr', 'Kızılgerdan Gürcistan''da nerede kaydedildi?', 'Kızılgerdan haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler gösterilir; diğer bölgeler gösterilmez. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Kızılgerdan gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('eryx-jaculus', 100411, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('eryx-jaculus', 'ka', 'სად არის დასავლური მახრჩობელა დაფიქსირებული საქართველოში', 'დასავლური მახრჩობელას რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს საქართველოში. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოკვეთილი; ცოტა ჩანაწერის მქონე რეგიონი არ გამოიკვეთება. დაფარული კოორდინატის მქონე ჩანაწერი რეგიონის სტატუსში არ ითვლება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'დასავლური მახრჩობელას დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('eryx-jaculus', 'en', 'Javelin sand boa: where it is recorded in Georgia', 'The javelin sand boa map uses Reptiles.ge editorial photo records and public iNaturalist observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; a region with too few records is not shaded. Records with obscured coordinates do not count towards a region''s status. Record counts reflect observation effort, not population density.', 'Javelin sand boa observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('eryx-jaculus', 'ru', 'Где западный удавчик отмечен в Грузии', 'Карта западного удавчика объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте выделены только регионы с достаточным числом записей; регион с малым числом записей не выделяется. Записи со скрытыми координатами не учитываются в статусе региона. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения западного удавчика и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('eryx-jaculus', 'tr', 'Cirit kum boası Gürcistan''da nerede kaydedildi?', 'Cirit kum boası haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve Gürcistan''daki herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler vurgulanır; kaydı az olan bölge vurgulanmaz. Koordinatı gizlenmiş kayıtlar bölgenin durumuna sayılmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Cirit kum boası gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('euscorpius-italicus', 56528, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('euscorpius-italicus', 'ka', 'სად არის იტალიური მორიელი დაფიქსირებული საქართველოში', 'იტალიური მორიელის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებს, Georgian Biodiversity Database-ის ლოკალიტეტებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან, ხოლო სტატუსი ერთმანეთისგან გამოყოფს საკმარისი ჩანაწერების მქონე რეგიონებსა და რეგიონებს, სადაც ჩანაწერები ცოტაა.', 'იტალიური მორიელის გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('euscorpius-italicus', 'en', 'Italian scorpion: where it is recorded in Georgia', 'The Italian scorpion map combines Reptiles.ge editorial photo records, Georgian Biodiversity Database localities, and public iNaturalist observations. Regions are taken from the records-by-region table, and the status column separates regions with enough records from regions with too few records.', 'Italian scorpion distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('euscorpius-italicus', 'ru', 'Где итальянский скорпион отмечен в Грузии', 'Карта итальянского скорпиона объединяет редакционные фотозаписи Reptiles.ge, локалитеты Georgian Biodiversity Database и публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам, а статус отделяет регионы с достаточным числом записей от регионов, где записей мало.', 'Данные о распространении итальянского скорпиона и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('euscorpius-italicus', 'tr', 'İtalyan akrebi Gürcistan''da nerede kaydedildi?', 'İtalyan akrebi haritası Reptiles.ge editoryal fotoğraf kayıtlarını, Georgian Biodiversity Database lokalitelerini ve herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; durum sütunu yeterli kaydı olan bölgeleri kaydı az olan bölgelerden ayırır.', 'İtalyan akrebinin Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('euscorpius-mingrelicus', 1654809, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('euscorpius-mingrelicus', 'ka', 'სად არის მეგრული მორიელი დაფიქსირებული საქართველოში', 'მეგრული მორიელის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან, ხოლო სტატუსი ერთმანეთისგან გამოყოფს საკმარისი ჩანაწერების მქონე რეგიონებსა და რეგიონებს, სადაც ჩანაწერები ცოტაა.', 'მეგრული მორიელის გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('euscorpius-mingrelicus', 'en', 'Mingrelian scorpion: where it is recorded in Georgia', 'The Mingrelian scorpion map combines Reptiles.ge editorial photo records with public iNaturalist observations. Regions are taken from the records-by-region table, and the status column separates regions with enough records from regions with too few records.', 'Mingrelian scorpion distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('euscorpius-mingrelicus', 'ru', 'Где мингрельский скорпион отмечен в Грузии', 'Карта мингрельского скорпиона объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам, а статус отделяет регионы с достаточным числом записей от регионов, где записей мало.', 'Данные о распространении мингрельского скорпиона и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('euscorpius-mingrelicus', 'tr', 'Karadeniz akrebi Gürcistan''da nerede kaydedildi?', 'Karadeniz akrebi haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; durum sütunu yeterli kaydı olan bölgeleri kaydı az olan bölgelerden ayırır.', 'Karadeniz akrebinin Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('falco-peregrinus', 4647, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('falco-peregrinus', 'ka', 'სად არის შავარდენი დაფიქსირებული საქართველოში', 'შავარდნის რუკა იყენებს საქართველოში iNaturalist-ის საჯარო ფოტოდაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მონიშნულია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები; დანარჩენში ჩანაწერები ცოტაა. ეს ჩანაწერები ბუდობას არ ადასტურებს, მათი რაოდენობა კი დაკვირვების ინტენსივობასაც ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'შავარდნის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('falco-peregrinus', 'en', 'Peregrine falcon: where it is recorded in Georgia', 'The peregrine falcon map uses public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions have too few records. These observations do not establish breeding, and record counts reflect observation effort rather than population density.', 'Peregrine falcon observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('falco-peregrinus', 'ru', 'Где сапсан отмечен в Грузии', 'Карта сапсана использует публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей; в остальных записей мало. Эти наблюдения не доказывают гнездование, а число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения сапсана и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('falco-peregrinus', 'tr', 'Gökdoğan Gürcistan''da nerede kaydedildi?', 'Gökdoğan haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler gösterilir; diğer bölgelerde kayıt azdır. Bu gözlemler üremeyi kanıtlamaz; kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını da yansıtır.', 'Gökdoğan gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('falco-tinnunculus', 472766, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('falco-tinnunculus', 'ka', 'სად არის კირკიტა დაფიქსირებული საქართველოში', 'კირკიტას რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან, ხოლო სტატუსი ერთმანეთისგან გამოყოფს საკმარისი ჩანაწერების მქონე რეგიონებსა და რეგიონებს, სადაც ჩანაწერები ცოტაა.', 'კირკიტას გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('falco-tinnunculus', 'en', 'Common kestrel: where it is recorded in Georgia', 'The common kestrel map combines Reptiles.ge editorial photo records with public iNaturalist observations. Regions are taken from the records-by-region table, and the status column separates regions with enough records from regions with too few records.', 'Common kestrel distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('falco-tinnunculus', 'ru', 'Где обыкновенная пустельга отмечена в Грузии', 'Карта обыкновенной пустельги объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам, а статус отделяет регионы с достаточным числом записей от регионов, где записей мало.', 'Данные о распространении обыкновенной пустельги и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('falco-tinnunculus', 'tr', 'Kerkenez Gürcistan''da nerede kaydedildi?', 'Kerkenez haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; durum sütunu yeterli kaydı olan bölgeleri kaydı az olan bölgelerden ayırır.', 'Kerkenezin Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('garrulus-glandarius', 8088, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('garrulus-glandarius', 'ka', 'სად არის ჩხიკვი დაფიქსირებული საქართველოში', 'ჩხიკვის რუკა საქართველოს iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მონიშნულია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები; დანარჩენი რეგიონები მონიშნული არ არის. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'ჩხიკვის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('garrulus-glandarius', 'en', 'Eurasian jay: where it is recorded in Georgia', 'The Eurasian jay map uses public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions are not shaded. Record counts reflect observation effort, not population density.', 'Eurasian jay observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('garrulus-glandarius', 'ru', 'Где сойка отмечена в Грузии', 'Карта сойки использует публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей; остальные регионы не закрашены. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения сойки и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('garrulus-glandarius', 'tr', 'Alakarga Gürcistan''da nerede kaydedildi?', 'Alakarga haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler gösterilir; diğer bölgeler gösterilmez. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Alakarga gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL);
