INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('gypaetus-barbatus', 'ka', 'სად არის ბატკანძერი დაფიქსირებული საქართველოში', 'ბატკანძერის რუკა საქართველოს iNaturalist-ის საჯარო დაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მონიშნულია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები, დანარჩენში ჩანაწერები ცოტაა. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'ბატკანძერის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('gypaetus-barbatus', 'en', 'Bearded vulture: where it is recorded in Georgia', 'The bearded vulture map uses public iNaturalist observations from Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions have too few records. Record counts reflect observation effort, not population density.', 'Bearded vulture observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('gypaetus-barbatus', 'ru', 'Где бородач отмечен в Грузии', 'Карта бородача основана на публичных наблюдениях iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей, в остальных регионах записей мало. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения бородача и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('gypaetus-barbatus', 'tr', 'Sakallı akbaba Gürcistan''da nerede kaydedildi?', 'Sakallı akbaba haritası Gürcistan''daki herkese açık iNaturalist gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan gelir: haritada yalnızca yeterli kaydı olan bölgeler gösterilir; diğerlerinde kayıt azdır. Kayıt sayısı gözlem çabasını yansıtır, popülasyon yoğunluğunu ölçmez.', 'Sakallı akbaba gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('gyps-fulvus', 5366, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('gyps-fulvus', 'ka', 'სად არის ორბი დაფიქსირებული საქართველოში', 'ორბის რუკა საქართველოს iNaturalist-ის საჯარო დაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მონიშნულია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები, დანარჩენში ჩანაწერები ცოტაა. დაკვირვება თავისთავად ბუდობას არ ადასტურებს. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'ორბის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('gyps-fulvus', 'en', 'Griffon vulture: where it is recorded in Georgia', 'The griffon vulture map uses public iNaturalist observations from Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions have too few records. Observations do not by themselves confirm nesting. Record counts reflect observation effort, not population density.', 'Griffon vulture observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('gyps-fulvus', 'ru', 'Где белоголовый сип отмечен в Грузии', 'Карта белоголового сипа основана на публичных наблюдениях iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей, в остальных регионах записей мало. Наблюдения сами по себе не подтверждают гнездование. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения белоголового сипа и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('gyps-fulvus', 'tr', 'Kızıl akbaba Gürcistan''da nerede kaydedildi?', 'Kızıl akbaba haritası Gürcistan''daki herkese açık iNaturalist gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan gelir: haritada yalnızca yeterli kaydı olan bölgeler gösterilir; diğerlerinde kayıt azdır. Gözlemler tek başına üremeyi doğrulamaz. Kayıt sayısı gözlem çabasını yansıtır, popülasyon yoğunluğunu ölçmez.', 'Kızıl akbaba gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL);
