INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('hemorrhois-ravergieri', 102628, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('hemorrhois-ravergieri', 'ka', 'სად არის ნაირფერი მცურავი დაფიქსირებული საქართველოში', 'ნაირფერი მცურავის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებს, საქართველოს საველე ლოკალიტეტებსა და iNaturalist-ის საჯარო ფოტოდაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: ხუთი ან მეტი ჩანაწერის მქონე რეგიონი რუკაზე მონიშნულია; ნაკლები ჩანაწერის მქონე რეგიონს „ჩანაწერები ცოტაა“ სტატუსი აქვს. iNaturalist-ის დაკვირვებები, რომელთა ამოცნობა ჯერ დადასტურებული არ არის, რუკაზე ჩანს, მაგრამ არ ითვლება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'ნაირფერი მცურავის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი საკმარისი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('hemorrhois-ravergieri', 'en', 'Spotted Whip Snake: where it is recorded in Georgia', 'The Spotted Whip Snake map combines Reptiles.ge editorial photo records, field localities from Georgia and public iNaturalist photo observations. Regions come from the records-by-region table: a region with five or more records is shaded on the map; a region with fewer records is marked as having too few records. iNaturalist observations that still need an ID are shown but not counted. Record counts reflect observation effort, not population density.', 'Spotted Whip Snake observations and regions with records on a map of Georgia', 'Region with records', 'regions with enough records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('hemorrhois-ravergieri', 'ru', 'Где пятнистый полоз отмечен в Грузии', 'Карта пятнистого полоза объединяет редакционные фотозаписи Reptiles.ge, полевые локалитеты из Грузии и публичные фотонаблюдения iNaturalist. Регионы взяты из таблицы записей: регион с пятью и более записями закрашен на карте; при меньшем числе у региона статус «Мало записей». Наблюдения iNaturalist, которым ещё нужно подтверждение определения, показаны, но не учитываются. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения пятнистого полоза и регионы с записями на карте Грузии', 'Регион с записями', 'региона с достаточным числом записей', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('hemorrhois-ravergieri', 'tr', 'Benekli kamçı yılanı Gürcistan''da nerede kaydedildi?', 'Benekli kamçı yılanı haritası Reptiles.ge editoryal fotoğraf kayıtlarını, Gürcistan''daki arazi lokalitelerini ve herkese açık iNaturalist fotoğraflı gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır: beş veya daha fazla kaydı olan bölge haritada gösterilir; daha az kaydı olan bölge “Kayıt az” olarak işaretlenir. Tür teşhisi henüz doğrulanmamış iNaturalist gözlemleri gösterilir ama sayılmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Benekli kamçı yılanı gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'yeterli kaydı olan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('hyla-orientalis', 70647, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('hyla-orientalis', 'ka', 'სად არის აღმოსავლური ვასაკა დაფიქსირებული საქართველოში', 'აღმოსავლური ვასაკას რუკა საქართველოში გაკეთებულ iNaturalist-ის საჯარო დაკვირვებებს ეყრდნობა. ჩანაწერების რეგიონული ცხრილი დაკვირვებებსა და დადასტურებულ გავრცელებას განასხვავებს: რუკაზე მხოლოდ დადასტურებული სტატუსის მქონე რეგიონი გამოიკვეთება. რეგიონი, სადაც მხოლოდ რამდენიმე ჩანაწერია, ცხრილში ჩანს, მაგრამ გავრცელებად არ ითვლება. iNaturalist-ის მიერ დაფარული კოორდინატი, ამოუცნობი დაკვირვება და თარიღის გარეშე შემთხვევითი დაკვირვება ამ სტატუსში არ ითვლება. ცალკეული წერტილები დაკვირვების ადგილებს აჩვენებს და არა პოპულაციის სიმჭიდროვეს.', 'აღმოსავლური ვასაკას დაკვირვებები და დადასტურებული რეგიონები საქართველოს რუკაზე', 'დადასტურებული რეგიონი', NULL, 'დადასტურებული გავრცელება');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('hyla-orientalis', 'en', 'Eastern Treefrog: where it is recorded in Georgia', 'The Eastern Treefrog map uses public iNaturalist observations in Georgia. The records-by-region table keeps observations separate from confirmed range: only a region with a confirmed status is shaded. A region with only a few records is listed but not counted as range. iNaturalist coordinates that are obscured, observations still awaiting identification and undated casual observations do not count toward that status. Individual points show observation locations, not population density.', 'Eastern Treefrog observations and confirmed regions on a map of Georgia', 'Confirmed region', NULL, 'Confirmed distribution');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('hyla-orientalis', 'ru', 'Где восточная квакша отмечена в Грузии', 'Карта восточной квакши основана на публичных наблюдениях iNaturalist в Грузии. Таблица записей по регионам отделяет наблюдения от подтверждённого ареала: на карте выделяются только регионы с подтверждённым статусом. Регион, где записей всего несколько, указан в таблице, но не считается частью ареала. Скрытые iNaturalist координаты, наблюдения, ожидающие определения, и случайные наблюдения без даты не учитываются для этого статуса. Отдельные точки показывают места наблюдений, а не плотность популяции.', 'Наблюдения восточной квакши и подтверждённые регионы на карте Грузии', 'Подтверждённый регион', NULL, 'Подтверждённое распространение');
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('hyla-orientalis', 'tr', 'Doğu ağaç kurbağası Gürcistan''da nerede kaydedildi?', 'Doğu ağaç kurbağası haritası Gürcistan''daki herkese açık iNaturalist gözlemlerine dayanır. Bölgelere göre kayıt tablosu gözlemleri doğrulanmış yayılıştan ayırır: haritada yalnızca doğrulanmış durumundaki bölge taranır. Yalnızca birkaç kaydı olan bölge tabloda görünür, ancak yayılış sayılmaz. iNaturalist''in gizlediği koordinatlar, henüz tanımlanmamış gözlemler ve tarihsiz rastgele gözlemler bu duruma sayılmaz. Tekil noktalar gözlem yerlerini gösterir, nüfus yoğunluğunu değil.', 'Doğu ağaç kurbağası gözlemleri ve doğrulanmış bölgeler Gürcistan haritasında', 'Doğrulanmış bölge', NULL, 'Doğrulanmış yayılış');
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('jynx-torquilla', 18448, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('jynx-torquilla', 'ka', 'სად არის მაქცია დაფიქსირებული საქართველოში', 'მაქციის რუკა საქართველოს iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოკვეთილი; ცოტა ჩანაწერის მქონე რეგიონი არ გამოიკვეთება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'მაქციის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('jynx-torquilla', 'en', 'Eurasian wryneck: where it is recorded in Georgia', 'The Eurasian wryneck map uses public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; a region with too few records is not shaded. Record counts reflect observation effort, not population density.', 'Eurasian wryneck observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('jynx-torquilla', 'ru', 'Где вертишейка отмечена в Грузии', 'Карта вертишейки использует публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте выделены только регионы с достаточным числом записей; регион с малым числом записей не выделяется. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения вертишейки и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('jynx-torquilla', 'tr', 'Boyunçeviren Gürcistan''da nerede kaydedildi?', 'Boyunçeviren haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler vurgulanır; kaydı az olan bölge vurgulanmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Boyunçeviren gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('lacerta-agilis', 35912, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('lacerta-agilis', 'ka', 'სად არის მარდი ხვლიკი დაფიქსირებული საქართველოში', 'მარდი ხვლიკის რუკა საქართველოს iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოკვეთილი; ცოტა ჩანაწერის მქონე რეგიონი არ გამოიკვეთება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'მარდი ხვლიკის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('lacerta-agilis', 'en', 'Sand lizard: where it is recorded in Georgia', 'The sand lizard map uses public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; a region with too few records is not shaded. Record counts reflect observation effort, not population density.', 'Sand lizard observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('lacerta-agilis', 'ru', 'Где прыткая ящерица отмечена в Грузии', 'Карта прыткой ящерицы использует публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте выделены только регионы с достаточным числом записей; регион с малым числом записей не выделяется. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения прыткой ящерицы и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('lacerta-agilis', 'tr', 'Kum kertenkelesi Gürcistan''da nerede kaydedildi?', 'Kum kertenkelesi haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler vurgulanır; kaydı az olan bölge vurgulanmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Kum kertenkelesi gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('lacerta-media', 73839, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('lacerta-media', 'ka', 'სად არის საშუალო ხვლიკი დაფიქსირებული საქართველოში', 'საშუალო ხვლიკის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს საქართველოში. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოკვეთილი; ცოტა ჩანაწერის მქონე რეგიონი არ გამოიკვეთება. დაფარული კოორდინატის ან დაუდასტურებელი სარკვევის მქონე ჩანაწერი რეგიონის სტატუსში არ ითვლება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'საშუალო ხვლიკის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('lacerta-media', 'en', 'Caucasian green lizard: where it is recorded in Georgia', 'The Caucasian green lizard map uses Reptiles.ge editorial photo records and public iNaturalist observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; a region with too few records is not shaded. Records with obscured coordinates or without a research-grade identification do not count towards a region''s status. Record counts reflect observation effort, not population density.', 'Caucasian green lizard observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('lacerta-media', 'ru', 'Где кавказская зелёная ящерица отмечена в Грузии', 'Карта кавказской зелёной ящерицы объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте выделены только регионы с достаточным числом записей; регион с малым числом записей не выделяется. Записи со скрытыми координатами или без подтверждённого определения не учитываются в статусе региона. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения кавказской зелёной ящерицы и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('lacerta-media', 'tr', 'Kafkas yeşil kertenkelesi Gürcistan''da nerede kaydedildi?', 'Kafkas yeşil kertenkelesi haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve Gürcistan''daki herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler vurgulanır; kaydı az olan bölge vurgulanmaz. Koordinatı gizlenmiş ya da tanımı doğrulanmamış kayıtlar bölgenin durumuna sayılmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Kafkas yeşil kertenkelesi gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('lacerta-strigata', 35870, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('lacerta-strigata', 'ka', 'სად არის ზოლიანი ხვლიკი დაფიქსირებული საქართველოში', 'ზოლიანი ხვლიკის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს საქართველოში. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოკვეთილი; ცოტა ჩანაწერის მქონე რეგიონი არ გამოიკვეთება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'ზოლიანი ხვლიკის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('lacerta-strigata', 'en', 'Striped lizard: where it is recorded in Georgia', 'The striped lizard map uses Reptiles.ge editorial photo records and public iNaturalist observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; a region with too few records is not shaded. Record counts reflect observation effort, not population density.', 'Striped lizard observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('lacerta-strigata', 'ru', 'Где полосатая ящерица отмечена в Грузии', 'Карта полосатой ящерицы объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте выделены только регионы с достаточным числом записей; регион с малым числом записей не выделяется. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения полосатой ящерицы и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('lacerta-strigata', 'tr', 'Çizgili kertenkele Gürcistan''da nerede kaydedildi?', 'Çizgili kertenkele haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve Gürcistan''daki herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler vurgulanır; kaydı az olan bölge vurgulanmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Çizgili kertenkele gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('lanius-collurio', 12038, 'record-summary', 1);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('lanius-collurio', 'ka', 'სად არის ჩვეულებრივი ღაჟო დაფიქსირებული საქართველოში', 'რუკა აჩვენებს ჩვეულებრივი ღაჟოს საჯარო, ფოტოიან დაკვირვებებს საქართველოში. გამოტოვებულია ჩანაწერები, რომელთა კოორდინატები დაფარულია, მეტისმეტად მიახლოებითია ან მითითებულ ადგილს არ ემთხვევა. გამოკვეთილი რეგიონი არ ნიშნავს, რომ ღაჟო მთელ რეგიონში თანაბრად გვხვდება. ჩანაწერების რაოდენობა არ გვიჩვენებს, რამდენი ღაჟო ბინადრობს ამა თუ იმ ადგილას.', 'ჩვეულებრივი ღაჟოს დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('lanius-collurio', 'en', 'Where the Red-backed Shrike is recorded in Georgia', 'The map shows public, photo-backed observations of the Red-backed Shrike in Georgia. Records whose coordinates are obscured, too approximate or do not match the stated place are left out. A shaded region does not mean the shrike occurs evenly across the whole region. Record counts do not show how many shrikes live in a given place.', 'Red-backed Shrike observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('lanius-collurio', 'ru', 'Где обыкновенный жулан отмечен в Грузии', 'Карта показывает публичные наблюдения обыкновенного жулана в Грузии, подтверждённые фотографиями. Записи, у которых координаты скрыты, слишком приблизительны или не совпадают с указанным местом, не показаны. Выделенный регион не значит, что жулан встречается по всему региону равномерно. Число записей не показывает, сколько жуланов обитает в том или ином месте.', 'Наблюдения обыкновенного жулана и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('lanius-collurio', 'tr', 'Kızılsırtlı örümcekkuşu Gürcistan''da nerede kaydedildi?', 'Harita, kızılsırtlı örümcekkuşunun Gürcistan''daki herkese açık, fotoğraflı gözlemlerini gösterir. Koordinatları gizlenmiş, fazla yaklaşık olan veya belirtilen yerle uyuşmayan kayıtlar haritaya alınmamıştır. Vurgulanan bölge, türün bölgenin her yerinde eşit biçimde görüldüğü anlamına gelmez. Kayıt sayısı, belirli bir yerde kaç kuş yaşadığını göstermez.', 'Kızılsırtlı örümcekkuşu gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('latrodectus-tredecimguttatus', 151791, 'record-summary', 1);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('latrodectus-tredecimguttatus', 'ka', 'სად არის ყარაყურთი დაფიქსირებული საქართველოში', 'ყარაყურთის რუკის რეგიონები ჩანაწერების რეგიონული ცხრილიდანაა. ერთი ჩანაწერიც საკმარისია, რომ რეგიონი რუკაზე გამოიკვეთოს; ჩანაწერის არმქონე რეგიონი არ გამოიკვეთება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'ყარაყურთის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('latrodectus-tredecimguttatus', 'en', 'Mediterranean black widow: where it is recorded in Georgia', 'The Mediterranean black widow map takes regions from its records-by-region table. One record is enough for a region to be shaded on the map; a region with no records is not shaded. Record counts reflect observation effort, not population density.', 'Mediterranean black widow observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('latrodectus-tredecimguttatus', 'ru', 'Где каракурт отмечен в Грузии', 'Регионы карты каракурта взяты из таблицы записей по регионам. Одной записи достаточно, чтобы регион был выделен на карте; регион без записей не выделяется. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения каракурта и регионы с записями на карте Грузии', 'Регион с записями', 'региона с записями', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('latrodectus-tredecimguttatus', 'tr', 'Karakurt Gürcistan''da nerede kaydedildi?', 'Karakurt haritasının bölgeleri, bölgelere göre kayıt tablosundan alınır. Bir bölgenin haritada vurgulanması için tek bir kayıt yeterlidir; kaydı olmayan bölge vurgulanmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Karakurt gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('lutra-lutra', 41850, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('lutra-lutra', 'ka', 'სად არის წავი დაფიქსირებული საქართველოში', 'წავის რუკა აერთიანებს Reptiles.ge-ის მიერ წყაროებიდან დამუშავებულ საველე ლოკალიტეტებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან, ხოლო სტატუსი ერთმანეთისგან გამოყოფს საკმარისი და ცოტა ჩანაწერის მქონე რეგიონებს.', 'წავის გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('lutra-lutra', 'en', 'Eurasian otter: where it is recorded in Georgia', 'The Eurasian otter map combines source-derived field localities curated by Reptiles.ge with public iNaturalist observations. Regions are taken from the records-by-region table, and the status column separates regions with enough records from regions with too few records.', 'Eurasian otter distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('lutra-lutra', 'ru', 'Где выдра отмечена в Грузии', 'Карта выдры объединяет полевые локалитеты, обработанные Reptiles.ge из источников, и публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам, а статус отделяет регионы с достаточным числом записей от регионов, где записей мало.', 'Данные о распространении выдры и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('lutra-lutra', 'tr', 'Su samuru Gürcistan''da nerede kaydedildi?', 'Su samuru haritası Reptiles.ge tarafından kaynaklardan işlenen arazi lokalitelerini ve herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; durum sütunu yeterli kaydı olan bölgeleri kaydı az olanlardan ayırır.', 'Su samurunun Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('macrovipera-lebetina', 105083, NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('macrovipera-lebetina', 'ka', 'სად გვხვდება გიურზა საქართველოში', 'გიურზას რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს. წყაროებით დადასტურებული რეგიონები და ინდივიდუალური საველე ჩანაწერები ცალკე ფენებია; ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და პოპულაციის სიმჭიდროვედ არ უნდა განვიხილოთ.', 'გიურზას გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', NULL, NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('macrovipera-lebetina', 'en', 'Levantine viper: where it occurs in Georgia', 'The Levantine viper map combines Reptiles.ge editorial photo records with public iNaturalist observations. Source-confirmed regions and individual field records are separate layers, and record counts reflect observation effort rather than population density.', 'Levantine viper distribution evidence and field records on a map of Georgia', NULL, NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('macrovipera-lebetina', 'ru', 'Где встречается гюрза в Грузии', 'Карта гюрзы объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist. Регионы, подтверждённые источниками, и отдельные полевые записи показаны разными слоями; количество записей отражает интенсивность наблюдений, а не плотность популяции.', 'Данные о распространении гюрзы и полевые записи на карте Грузии', NULL, NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('macrovipera-lebetina', 'tr', 'Levant engereği Gürcistan''da nerede görülür?', 'Levant engereği haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve herkese açık iNaturalist gözlemlerini birleştirir. Kaynakla doğrulanmış bölgeler ile tekil arazi kayıtları ayrı katmanlardır; kayıt sayısı gözlem yoğunluğunu yansıtır, popülasyon yoğunluğu değildir.', 'Levant engereğinin Gürcistan''daki yayılış kanıtları ve arazi kayıtları', NULL, NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('mantis-religiosa', 53905, NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('mantis-religiosa', 'ka', 'სად არის ჩოქელა დაფიქსირებული საქართველოში', 'ჩოქელას რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს. ინდივიდუალური საველე ჩანაწერები წერტილებადაა ნაჩვენები; ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და პოპულაციის სიმჭიდროვედ არ უნდა განვიხილოთ.', 'ჩოქელას საველე ჩანაწერები საქართველოს რუკაზე', NULL, NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('mantis-religiosa', 'en', 'European mantis: where it is recorded in Georgia', 'The European mantis map combines Reptiles.ge editorial photo records with public iNaturalist observations. Individual field records are shown as point data, and record counts reflect observation effort rather than population density.', 'European mantis field records on a map of Georgia', NULL, NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('mantis-religiosa', 'ru', 'Где богомол отмечен в Грузии', 'Карта богомола объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist. Отдельные полевые записи показаны точками; количество записей отражает интенсивность наблюдений, а не плотность популяции.', 'Полевые записи богомола на карте Грузии', NULL, NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('mantis-religiosa', 'tr', 'Peygamberdevesi Gürcistan''da nerede kaydedildi?', 'Peygamberdevesi haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve herkese açık iNaturalist gözlemlerini birleştirir. Tekil arazi kayıtları nokta verisi olarak gösterilir; kayıt sayısı gözlem yoğunluğunu yansıtır, popülasyon yoğunluğu değildir.', 'Peygamberdevesi arazi kayıtları Gürcistan haritasında', NULL, NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('mauremys-caspica', 39972, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('mauremys-caspica', 'ka', 'სად არის კასპიური კუ დაფიქსირებული საქართველოში', 'კასპიური კუს რუკა აჩვენებს iNaturalist-ის საჯარო დაკვირვებებს საქართველოში. რუკაზე მხოლოდ ის რეგიონებია გამოკვეთილი, რომლებსაც ჩანაწერების ცხრილში საკმარისი ჩანაწერი აქვს. ზოგი საჯარო კოორდინატი დაფარული ან მიახლოებითია, ზოგჯერ კი ლოკალიტეტის ტექსტი წერტილის რეგიონს არ ემთხვევა. გამოკვეთილი რეგიონი არ ნიშნავს მის მთელ ტერიტორიაზე გავრცელებას; ჩანაწერების რაოდენობა პოპულაციის სიმჭიდროვეს არ ზომავს.', 'კასპიური კუს საველე ჩანაწერები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('mauremys-caspica', 'en', 'Where Caspian turtles are recorded in Georgia', 'The Caspian turtle map shows public iNaturalist observations in Georgia. Only regions with enough records in the records table are shaded on the map. Some public coordinates are obscured or approximate, and locality text can disagree with a point''s region. A shaded region does not mean the turtle occupies all of it; record counts reflect observation effort, not population density.', 'Caspian turtle field records and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('mauremys-caspica', 'ru', 'Где каспийская черепаха отмечена в Грузии', 'Карта каспийской черепахи показывает публичные наблюдения iNaturalist в Грузии. На карте выделены только регионы с достаточным числом записей в таблице записей. Некоторые публичные координаты скрыты или приблизительны, а текст местонахождения иногда не совпадает с регионом точки. Выделенный регион не означает присутствие на всей его территории; число записей не измеряет плотность популяции.', 'Полевые записи каспийской черепахи и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('mauremys-caspica', 'tr', 'Hazar kaplumbağası Gürcistan''da nerede kaydedildi?', 'Hazar kaplumbağası haritası Gürcistan''daki herkese açık iNaturalist gözlemlerini gösterir. Haritada yalnızca kayıt tablosunda yeterli kaydı olan bölgeler vurgulanır. Bazı açık koordinatlar gizlenmiş veya yaklaşıktır; yer adı bazen noktanın bulunduğu bölgeyle uyuşmaz. Vurgulanan bölge türün her yerinde bulunduğu anlamına gelmez; kayıt sayısı popülasyon yoğunluğunu ölçmez.', 'Hazar kaplumbağasının arazi kayıtları ve kayıt bulunan bölgeleri Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('meles-canescens', 855298, 'record-summary', 1);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('meles-canescens', 'ka', 'სად არის მაჩვი დაფიქსირებული საქართველოში', 'მაჩვის რუკა საქართველოს iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოკვეთილი; ცოტა ჩანაწერის მქონე რეგიონი არ გამოიკვეთება. რეგიონული პოლიგონების გარეთ დარჩენილი წერტილები საერთო რაოდენობაში შედის, მაგრამ რეგიონს არ მიეკუთვნება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'მაჩვის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('meles-canescens', 'en', 'Where the Caucasian badger is recorded in Georgia', 'The Caucasian badger map uses public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; a region with too few records is not shaded. Points outside the regional polygons stay in the total but are not assigned to a region. Record counts reflect observation effort, not population density.', 'Caucasian badger observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('meles-canescens', 'ru', 'Где кавказский барсук отмечен в Грузии', 'Карта кавказского барсука использует публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте выделены только регионы с достаточным числом записей; регион с малым числом записей не выделяется. Точки вне региональных полигонов входят в общее число, но к региону не относятся. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения кавказского барсука и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('meles-canescens', 'tr', 'Kafkas porsuğu Gürcistan''da nerede kaydedildi?', 'Kafkas porsuğu haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler vurgulanır; kaydı az olan bölge vurgulanmaz. Bölge poligonlarının dışında kalan noktalar toplama girer ama bir bölgeye yazılmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Kafkas porsuğu gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('mertensiella-caucasica', 27853, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('mertensiella-caucasica', 'ka', 'სად არის კავკასიური სალამანდრა დაფიქსირებული საქართველოში', '2026 წლის ჩამონათვალში დასახელებული ლოკალიტეტები ადასტურებს ჩანაწერებს აჭარაში, გურიაში, სამცხე–ჯავახეთსა და შიდა ქართლში. დადასტურებული სტატუსის საფუძველი ეს წყაროა და არა დაკვირვებების რაოდენობა. iNaturalist M. djanaschvilii-ს ცალკე ტაქსონად აჩვენებს, ამიტომ აქ მხოლოდ iNaturalist-ის M. caucasica ტაქსონის ჩანაწერებია. საჯარო კოორდინატები დაახლოებით 27 კმ-ითაა დაფარული; წერტილები და მათი რეგიონული დათვლა მიახლოებითია და საზღვარს შეიძლება გადასცდეს. რაოდენობა არც პოპულაციის სიმჭიდროვეს ზომავს და არც მთელი რეგიონის უწყვეტ გავრცელებას ნიშნავს.', 'კავკასიური სალამანდრას წყაროთი დადასტურებული რეგიონები და მიახლოებითი დაკვირვებები საქართველოს რუკაზე', 'წყაროთი დადასტურებული გავრცელების რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('mertensiella-caucasica', 'en', 'Caucasian salamander: where it is documented in Georgia', 'The 2026 checklist names sites in Adjara, Guria, Samtskhe–Javakheti and Shida Kartli. These named localities, not observation counts, support the confirmed regions. iNaturalist lists M. djanaschvilii separately, so these records cover only iNaturalist''s M. caucasica taxon. Public coordinates are obscured by roughly 27 km; plotted points and their region counts are approximate and may cross borders. Counts reflect observations, not population density or a range across each whole region.', 'Caucasian salamander source-confirmed regions and approximate observations on a map of Georgia', 'Source-confirmed distribution region', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('mertensiella-caucasica', 'ru', 'Где кавказская саламандра отмечена в Грузии', 'В чек-листе 2026 года названы местонахождения в Аджарии, Гурии, Самцхе–Джавахети и Шида-Картли. Статус подтверждённых регионов основан на этих местонахождениях, а не на числе наблюдений. iNaturalist учитывает M. djanaschvilii отдельно, поэтому здесь показаны записи только таксона M. caucasica по iNaturalist. Публичные координаты скрыты примерно на 27 км; точки и их распределение по регионам приблизительны и могут пересекать границы. Число записей не измеряет плотность популяции и не означает сплошное распространение по всему региону.', 'Подтверждённые источником регионы и приблизительные наблюдения кавказской саламандры на карте Грузии', 'Регион распространения, подтверждённый источником', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('mertensiella-caucasica', 'tr', 'Kafkas semenderi Gürcistan''da nerede kaydedildi?', '2026 kontrol listesi Acara, Guria, Samtshe–Cavaheti ve Şida Kartli''de belirli lokaliteler bildirir. Doğrulanmış bölge durumu gözlem sayısına değil, bu lokalitelere dayanır. iNaturalist M. djanaschvilii''yi ayrı listeler; burada yalnızca M. caucasica taksonunun kayıtları vardır. Herkese açık koordinatlar yaklaşık 27 km gizlenmiştir; noktalar ve bölgesel sayımları yaklaşıktır ve sınırları aşabilir. Kayıt sayısı popülasyon yoğunluğunu ya da bütün bölgeye yayılışı göstermez.', 'Kafkas semenderinin kaynakla doğrulanmış bölgeleri ve yaklaşık gözlemleri Gürcistan haritasında', 'Kaynakla doğrulanmış yayılış bölgesi', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('mesobuthus-eupeus', 709915, NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('mesobuthus-eupeus', 'ka', 'სად არის ჭრელი მორიელი დაფიქსირებული საქართველოში', 'ჭრელი მორიელის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს. წყაროებით დადასტურებული რეგიონები და ინდივიდუალური საველე ჩანაწერები ცალკე ფენებია; ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და პოპულაციის სიმჭიდროვედ არ უნდა განვიხილოთ.', 'ჭრელი მორიელის გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', NULL, NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('mesobuthus-eupeus', 'en', 'Mottled scorpion: where it is recorded in Georgia', 'The mottled scorpion map combines Reptiles.ge editorial photo records with public iNaturalist observations. Source-confirmed regions and individual field records are separate layers, and record counts reflect observation effort rather than population density.', 'Mottled scorpion distribution evidence and field records on a map of Georgia', NULL, NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('mesobuthus-eupeus', 'ru', 'Где пёстрый скорпион отмечен в Грузии', 'Карта пёстрого скорпиона объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist. Регионы, подтверждённые источниками, и отдельные полевые записи показаны разными слоями; количество записей отражает интенсивность наблюдений, а не плотность популяции.', 'Данные о распространении пёстрого скорпиона и полевые записи на карте Грузии', NULL, NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('mesobuthus-eupeus', 'tr', 'Alacalı akrep Gürcistan''da nerede kaydedildi?', 'Alacalı akrep haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve herkese açık iNaturalist gözlemlerini birleştirir. Kaynakla doğrulanmış bölgeler ile tekil arazi kayıtları ayrı katmanlardır; kayıt sayısı gözlem yoğunluğunu yansıtır, popülasyon yoğunluğu değildir.', 'Alacalı akrebin Gürcistan''daki yayılış kanıtları ve arazi kayıtları', NULL, NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('mustela-nivalis', 569428, 'record-summary', 1);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('mustela-nivalis', 'ka', 'სად არის დედოფალა დაფიქსირებული საქართველოში', 'დედოფალას რუკა აერთიანებს Reptiles.ge-ის საველე ფოტოებსა და iNaturalist-ის საჯარო ფოტოდაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან; ამ სახეობაზე ერთი ჩანაწერიც საკმარისია, რომ რეგიონი რუკაზე გამოიკვეთოს. გამოკვეთილი რეგიონი მის მთელ ტერიტორიაზე არსებობას არ ნიშნავს, ხოლო ჩანაწერების რაოდენობა პოპულაციის სიმჭიდროვე არ არის.', 'დედოფალას ფოტოდაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('mustela-nivalis', 'en', 'Least weasel: where it is recorded in Georgia', 'The least weasel map combines Reptiles.ge field photos with public iNaturalist photo observations. Regions come from the records-by-region table; for this species, one record is enough for a region to be shaded on the map. A highlighted region does not imply presence throughout it, and record counts do not measure population density.', 'Least weasel photo observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('mustela-nivalis', 'ru', 'Где ласка отмечена в Грузии', 'Карта ласки объединяет полевые фотографии Reptiles.ge и публичные фотонаблюдения iNaturalist. Регионы взяты из таблицы записей; для этого вида одной записи достаточно, чтобы регион был выделен на карте. Выделенный регион не означает присутствия на всей его территории, а число записей не измеряет плотность популяции.', 'Фотонаблюдения ласки и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('mustela-nivalis', 'tr', 'Gelincik Gürcistan''da nerede kaydedildi?', 'Gelincik haritası Reptiles.ge arazi fotoğraflarını ve herkese açık iNaturalist fotoğraflı gözlemlerini birleştirir. Bölgeler kayıt tablosundan alınır; bu türde bir bölgenin haritada vurgulanması için tek bir kayıt yeterlidir. Vurgulanan bölge türün her yerinde bulunduğu anlamına gelmez; kayıt sayısı popülasyon yoğunluğunu ölçmez.', 'Gelincik fotoğraflı gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('natrix-natrix', 966787, 'record-summary', 1);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('natrix-natrix', 'ka', 'სად არის ჩვეულებრივი ანკარა დაფიქსირებული საქართველოში', 'ჩვეულებრივი ანკარის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან; ამ სახეობაზე ერთი ჩანაწერიც საკმარისია, რომ რეგიონი რუკაზე გამოიკვეთოს.', 'ჩვეულებრივი ანკარის გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('natrix-natrix', 'en', 'Grass snake: where it is recorded in Georgia', 'The grass snake map combines Reptiles.ge editorial photo records with public iNaturalist observations. Regions are taken from the records-by-region table; for this species, a region with at least one record is shaded on the map.', 'Grass snake distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('natrix-natrix', 'ru', 'Где обыкновенный уж отмечен в Грузии', 'Карта обыкновенного ужа объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам; для этого вида одного наблюдения достаточно, чтобы регион был выделен на карте.', 'Данные о распространении обыкновенного ужа и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('natrix-natrix', 'tr', 'Çim yılanı Gürcistan''da nerede kaydedildi?', 'Çim yılanı haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; bu tür için en az bir kayıt bulunan bölge haritada vurgulanır.', 'Çim yılanının Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('natrix-tessellata', 64346, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('natrix-tessellata', 'ka', 'სად არის წყლის ანკარა დაფიქსირებული საქართველოში', 'წყლის ანკარის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან და რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოკვეთილი.', 'წყლის ანკარის გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('natrix-tessellata', 'en', 'Dice snake: where it is recorded in Georgia', 'The dice snake map combines Reptiles.ge editorial photo records with public iNaturalist observations. Regions are taken from the records-by-region table, and only regions with enough records are shaded on the map.', 'Dice snake distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('natrix-tessellata', 'ru', 'Где водяной уж отмечен в Грузии', 'Карта водяного ужа объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам; на карте выделены только регионы с достаточным числом записей.', 'Данные о распространении водяного ужа и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('natrix-tessellata', 'tr', 'Kareli yılan Gürcistan''da nerede kaydedildi?', 'Kareli yılan haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; haritada yalnızca yeterli kaydı olan bölgeler vurgulanır.', 'Kareli yılanın Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('neophron-percnopterus', 5361, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('neophron-percnopterus', 'ka', 'სად არის ფასკუნჯი დაფიქსირებული საქართველოში', 'ფასკუნჯის რუკა საქართველოს iNaturalist-ის საჯარო დაკვირვებებსა და სარედაქციო ფოტოჩანაწერებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოკვეთილი, დანარჩენში ჩანაწერები ცოტაა. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'ფასკუნჯის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('neophron-percnopterus', 'en', 'Egyptian vulture: where it is recorded in Georgia', 'The Egyptian vulture map uses public iNaturalist observations from Georgia together with editorial photo records. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions have too few records. Record counts reflect observation effort, not population density.', 'Egyptian vulture observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('neophron-percnopterus', 'ru', 'Где стервятник отмечен в Грузии', 'Карта стервятника основана на публичных наблюдениях iNaturalist в Грузии и редакционных фотозаписях. Регионы взяты из таблицы записей: на карте выделены только регионы с достаточным числом записей, в остальных записей мало. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения стервятника и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('neophron-percnopterus', 'tr', 'Küçük akbaba Gürcistan''da nerede kaydedildi?', 'Küçük akbaba haritası Gürcistan''daki herkese açık iNaturalist gözlemlerini ve editoryal fotoğraf kayıtlarını kullanır. Bölgeler, bölgelere göre kayıt tablosundan gelir: haritada yalnızca yeterli kaydı olan bölgeler vurgulanır; diğerlerinde kayıt azdır. Kayıt sayısı gözlem çabasını yansıtır, popülasyon yoğunluğunu ölçmez.', 'Küçük akbaba gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('ommatotriton-ophryticus', 64364, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('ommatotriton-ophryticus', 'ka', 'სად არის კავკასიური ტრიტონი დაფიქსირებული საქართველოში', 'კავკასიური ტრიტონის რუკა საქართველოში გაკეთებულ iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. iNaturalist ამ სახეობის ყველა საჯარო კოორდინატს დაახლოებით 20 კმ-იან უჯრაში ფარავს, ამიტომ წერტილი მიახლოებითია. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: ხუთი ან მეტი ჩანაწერის მქონე რეგიონი რუკაზე მონიშნულია; ნაკლები ჩანაწერის მქონე რეგიონს „ჩანაწერები ცოტაა“ სტატუსი აქვს. ჩანაწერი, რომლის დაფარული უჯრა რეგიონის საზღვარს კვეთს, და დაკვირვება, რომლის ამოცნობა ჯერ დადასტურებული არ არის, რუკაზე ჩანს, მაგრამ არ ითვლება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'კავკასიური ტრიტონის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი საკმარისი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('ommatotriton-ophryticus', 'en', 'Northern Banded Newt: where it is recorded in Georgia', 'The Northern Banded Newt map uses public iNaturalist photo observations in Georgia. iNaturalist obscures every public coordinate for this species within a cell of about 20 km, so a point is approximate. Regions come from the records-by-region table: a region with five or more records is shaded on the map; a region with fewer records is marked as having too few records. A record whose obscured cell crosses a regional border, and an observation that still needs an ID, is shown but not counted. Record counts reflect observation effort, not population density.', 'Northern Banded Newt observations and regions with records on a map of Georgia', 'Region with records', 'regions with enough records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('ommatotriton-ophryticus', 'ru', 'Где северный полосатый тритон отмечен в Грузии', 'Карта северного полосатого тритона основана на публичных фотонаблюдениях iNaturalist в Грузии. iNaturalist скрывает все публичные координаты этого вида в ячейке около 20 км, поэтому точка приблизительна. Регионы взяты из таблицы записей: регион с пятью и более записями закрашен на карте; при меньшем числе у региона статус «Мало записей». Запись, скрытая ячейка которой пересекает границу региона, и наблюдение, которому ещё нужно подтверждение определения, показаны, но не учитываются. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения северного полосатого тритона и регионы с записями на карте Грузии', 'Регион с записями', 'региона с достаточным числом записей', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('ommatotriton-ophryticus', 'tr', 'Kuzey şeritli semender Gürcistan''da nerede kaydedildi?', 'Kuzey şeritli semender haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerine dayanır. iNaturalist bu türün tüm açık koordinatlarını yaklaşık 20 km''lik bir hücre içinde gizler, bu yüzden nokta yaklaşıktır. Bölgeler, bölgelere göre kayıt tablosundan alınır: beş veya daha fazla kaydı olan bölge haritada gösterilir; daha az kaydı olan bölge “Kayıt az” olarak işaretlenir. Gizli hücresi bölge sınırını kesen kayıt ve tür teşhisi henüz doğrulanmamış gözlem gösterilir ama sayılmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Kuzey şeritli semender gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'yeterli kaydı olan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('paralaudakia-caucasia', 318730, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('paralaudakia-caucasia', 'ka', 'სად არის ჯოჯო დაფიქსირებული საქართველოში', 'ჯოჯოს რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან და რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოკვეთილი.', 'ჯოჯოს გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('paralaudakia-caucasia', 'en', 'Caucasian agama: where it is recorded in Georgia', 'The Caucasian agama map combines Reptiles.ge editorial photo records with public iNaturalist observations. Regions are taken from the records-by-region table, and only regions with enough records are shaded on the map.', 'Caucasian agama distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('paralaudakia-caucasia', 'ru', 'Где кавказская агама отмечена в Грузии', 'Карта кавказской агамы объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам; на карте выделены только регионы с достаточным числом записей.', 'Данные о распространении кавказской агамы и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('paralaudakia-caucasia', 'tr', 'Kafkas keleri Gürcistan''da nerede kaydedildi?', 'Kafkas keleri haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; haritada yalnızca yeterli kaydı olan bölgeler vurgulanır.', 'Kafkas kelerinin Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('pelobates-syriacus', 25313, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('pelobates-syriacus', 'ka', 'სად არის სირიული მყვარი დაფიქსირებული საქართველოში', 'სირიული მყვრის რუკა საქართველოში გაკეთებულ iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. iNaturalist ამ სახეობის საჯარო კოორდინატების უმეტესობას დაახლოებით 20 კმ-იან უჯრაში ფარავს, ამიტომ ბევრი წერტილი მიახლოებითია. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: ხუთი ან მეტი ჩანაწერის მქონე რეგიონი რუკაზე მონიშნულია; ნაკლები ჩანაწერის მქონე რეგიონს „ჩანაწერები ცოტაა“ სტატუსი აქვს. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'სირიული მყვრის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი საკმარისი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('pelobates-syriacus', 'en', 'Eastern Spadefoot: where it is recorded in Georgia', 'The Eastern Spadefoot map uses public iNaturalist photo observations in Georgia. iNaturalist obscures most public coordinates for this species within a cell of about 20 km, so many points are approximate. Regions come from the records-by-region table: a region with five or more records is shaded on the map; a region with fewer records is marked as having too few records. Record counts reflect observation effort, not population density.', 'Eastern Spadefoot observations and regions with records on a map of Georgia', 'Region with records', 'regions with enough records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('pelobates-syriacus', 'ru', 'Где восточная чесночница отмечена в Грузии', 'Карта восточной чесночницы основана на публичных фотонаблюдениях iNaturalist в Грузии. iNaturalist скрывает большинство публичных координат этого вида в ячейке около 20 км, поэтому многие точки приблизительны. Регионы взяты из таблицы записей: регион с пятью и более записями закрашен на карте; при меньшем числе у региона статус «Мало записей». Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения восточной чесночницы и регионы с записями на карте Грузии', 'Регион с записями', 'региона с достаточным числом записей', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('pelobates-syriacus', 'tr', 'Doğu kazayak kurbağası Gürcistan''da nerede kaydedildi?', 'Doğu kazayak kurbağası haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerine dayanır. iNaturalist bu türün açık koordinatlarının çoğunu yaklaşık 20 km''lik bir hücre içinde gizler, bu yüzden birçok nokta yaklaşıktır. Bölgeler, bölgelere göre kayıt tablosundan alınır: beş veya daha fazla kaydı olan bölge haritada gösterilir; daha az kaydı olan bölge “Kayıt az” olarak işaretlenir. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Doğu kazayak kurbağası gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'yeterli kaydı olan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('pelodytes-caucasicus', 25317, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('pelodytes-caucasicus', 'ka', 'სად არის კავკასიური ჯვრიანა დაფიქსირებული საქართველოში', 'კავკასიური ჯვრიანას რუკა საქართველოში გაკეთებულ iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. iNaturalist ამ სახეობის ყველა საჯარო კოორდინატს დაახლოებით 20 კმ-იან უჯრაში ფარავს, ამიტომ წერტილები მიახლოებითია. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: ხუთი ან მეტი ჩანაწერის მქონე რეგიონი რუკაზე მონიშნულია; ნაკლები ჩანაწერის მქონე რეგიონს „ჩანაწერები ცოტაა“ სტატუსი აქვს. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'კავკასიური ჯვრიანას დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი საკმარისი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('pelodytes-caucasicus', 'en', 'Caucasian Parsley Frog: where it is recorded in Georgia', 'The Caucasian Parsley Frog map uses public iNaturalist photo observations in Georgia. iNaturalist obscures all public coordinates for this species within a cell of about 20 km, so the points are approximate. Regions come from the records-by-region table: a region with five or more records is shaded on the map; a region with fewer records is marked as having too few records. Record counts reflect observation effort, not population density.', 'Caucasian Parsley Frog observations and regions with records on a map of Georgia', 'Region with records', 'regions with enough records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('pelodytes-caucasicus', 'ru', 'Где кавказская крестовка отмечена в Грузии', 'Карта кавказской крестовки основана на публичных фотонаблюдениях iNaturalist в Грузии. iNaturalist скрывает все публичные координаты этого вида в ячейке около 20 км, поэтому точки приблизительны. Регионы взяты из таблицы записей: регион с пятью и более записями закрашен на карте; при меньшем числе у региона статус «Мало записей». Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения кавказской крестовки и регионы с записями на карте Грузии', 'Регион с записями', 'региона с достаточным числом записей', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('pelodytes-caucasicus', 'tr', 'Kafkas maydanoz kurbağası Gürcistan''da nerede kaydedildi?', 'Kafkas maydanoz kurbağası haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerine dayanır. iNaturalist bu türün tüm açık koordinatlarını yaklaşık 20 km''lik bir hücre içinde gizler, bu yüzden noktalar yaklaşıktır. Bölgeler, bölgelere göre kayıt tablosundan alınır: beş veya daha fazla kaydı olan bölge haritada gösterilir; daha az kaydı olan bölge “Kayıt az” olarak işaretlenir. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Kafkas maydanoz kurbağası gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'yeterli kaydı olan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('pelophylax-ridibundus', 1319807, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('pelophylax-ridibundus', 'ka', 'სად არის ტბორის ბაყაყი დაფიქსირებული საქართველოში', 'ტბორის ბაყაყის რუკა საქართველოში გაკეთებულ iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: ხუთი ან მეტი ჩანაწერის მქონე რეგიონი რუკაზე მონიშნულია; ნაკლები ჩანაწერის მქონე რეგიონს „ჩანაწერები ცოტაა“ სტატუსი აქვს. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'ტბორის ბაყაყის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი საკმარისი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('pelophylax-ridibundus', 'en', 'Marsh Frog: where it is recorded in Georgia', 'The Marsh Frog map uses public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: a region with five or more records is shaded on the map; a region with fewer records is marked as having too few records. Record counts reflect observation effort, not population density.', 'Marsh Frog observations and regions with records on a map of Georgia', 'Region with records', 'regions with enough records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('pelophylax-ridibundus', 'ru', 'Где озёрная лягушка отмечена в Грузии', 'Карта озёрной лягушки основана на публичных фотонаблюдениях iNaturalist в Грузии. Регионы взяты из таблицы записей: регион с пятью и более записями закрашен на карте; при меньшем числе у региона статус «Мало записей». Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения озёрной лягушки и регионы с записями на карте Грузии', 'Регион с записями', 'региона с достаточным числом записей', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('pelophylax-ridibundus', 'tr', 'Göl kurbağası Gürcistan''da nerede kaydedildi?', 'Göl kurbağası haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerine dayanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: beş veya daha fazla kaydı olan bölge haritada gösterilir; daha az kaydı olan bölge “Kayıt az” olarak işaretlenir. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Göl kurbağası gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'yeterli kaydı olan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('phasianus-colchicus', 981, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('phasianus-colchicus', 'ka', 'სად არის ხოხობი დაფიქსირებული საქართველოში', 'ხოხბის რუკა იყენებს საქართველოში iNaturalist-ის საჯარო დაკვირვებებს, რომლებიც ტყვეობაში მყოფად არ არის მონიშნული. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან; რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოკვეთილი. ჩანაწერების რაოდენობა პოპულაციის სიმჭიდროვეს არ ნიშნავს.', 'ხოხბის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერებით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('phasianus-colchicus', 'en', 'Common pheasant: where it is recorded in Georgia', 'The common pheasant map uses public iNaturalist observations from Georgia that are not marked captive. Regions come from the records-by-region table; only regions with enough records are shaded on the map. Record counts reflect observation effort, not population density.', 'Common pheasant observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('phasianus-colchicus', 'ru', 'Где фазан отмечен в Грузии', 'Карта фазана использует публичные наблюдения из Грузии на iNaturalist, не отмеченные как содержащиеся в неволе. Регионы взяты из таблицы записей; на карте выделены только регионы с достаточным числом записей. Число записей не означает плотность популяции.', 'Наблюдения фазана и регионы с записями на карте Грузии', 'Регион с записями', 'регионы с записями', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('phasianus-colchicus', 'tr', 'Sülün Gürcistan''da nerede kaydedildi?', 'Sülün haritası Gürcistan''daki esir olarak işaretlenmemiş halka açık iNaturalist gözlemlerini kullanır. Bölgeler, bölgesel kayıt tablosundan alınır; haritada yalnızca yeterli kaydı olan bölgeler vurgulanır. Kayıt sayısı nüfus yoğunluğunu göstermez.', 'Sülün gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('picus-viridis', 144243, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('picus-viridis', 'ka', 'სად არის მწვანე კოდალა დაფიქსირებული საქართველოში', 'მწვანე კოდალას რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს საქართველოში. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონებია გამოკვეთილი; ცოტა ჩანაწერის მქონე რეგიონი არ გამოიკვეთება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'მწვანე კოდალას დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('picus-viridis', 'en', 'European green woodpecker: where it is recorded in Georgia', 'The European green woodpecker map uses Reptiles.ge editorial photo records and public iNaturalist observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; a region with too few records is not shaded. Record counts reflect observation effort, not population density.', 'European green woodpecker observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('picus-viridis', 'ru', 'Где зелёный дятел отмечен в Грузии', 'Карта зелёного дятла объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте выделены только регионы с достаточным числом записей; регион с малым числом записей не выделяется. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения зелёного дятла и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('picus-viridis', 'tr', 'Yeşil ağaçkakan Gürcistan''da nerede kaydedildi?', 'Yeşil ağaçkakan haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve Gürcistan''daki herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler vurgulanır; kaydı az olan bölge vurgulanmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Yeşil ağaçkakan gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('platyceps-najadum', 73910, 'record-summary', 3);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('platyceps-najadum', 'ka', 'სად არის წენგოსფერი მცურავი დაფიქსირებული საქართველოში', 'წენგოსფერი მცურავის რუკა აერთიანებს Reptiles.ge-ის საველე ფოტოებსა და iNaturalist-ის საჯარო დაკვირვებებს. შეფერილი რეგიონები რეგიონული ცხრილის სტატუსს ეფუძნება: რუკაზე შეფერილია სულ მცირე 3 საველე ჩანაწერის მქონე რეგიონი; 1–2 ჩანაწერი ცოტად ითვლება. ჩანაწერების რაოდენობა პოპულაციის სიმჭიდროვე არ არის.', 'წენგოსფერი მცურავის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('platyceps-najadum', 'en', 'Dahl''s whip snake: where it is recorded in Georgia', 'The Dahl''s whip snake map combines Reptiles.ge field photos with public iNaturalist observations. The records-by-region table determines the shaded range: regions with three or more field records are shaded on the map; one or two records count as too few records. Record counts do not measure population density.', 'Dahl''s whip snake observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('platyceps-najadum', 'ru', 'Где оливковый полоз отмечен в Грузии', 'Карта оливкового полоза объединяет полевые фотографии Reptiles.ge и публичные наблюдения iNaturalist. Закрашенные регионы определяются региональной таблицей: на карте закрашены регионы с тремя и более полевыми записями; одной или двух записей мало. Число записей не отражает плотность популяции.', 'Наблюдения оливкового полоза и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('platyceps-najadum', 'tr', 'Dahl kırbaç yılanı Gürcistan''da nerede kaydedildi?', 'Dahl kırbaç yılanı haritası Reptiles.ge arazi fotoğraflarını ve herkese açık iNaturalist gözlemlerini birleştirir. Boyalı bölgeler bölgesel tabloya dayanır: üç veya daha fazla arazi kaydı olan bölgeler haritada boyanır; bir veya iki kayıt az sayılır. Kayıt sayısı popülasyon yoğunluğunu göstermez.', 'Dahl kırbaç yılanı gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('procyon-lotor', 41663, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('procyon-lotor', 'ka', 'სად არის ენოტი დაფიქსირებული საქართველოში', 'ენოტის რუკა საქართველოს iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე შეფერილია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები; დანარჩენი რეგიონები შეფერილი არ არის. რეგიონული პოლიგონების გარეთ დარჩენილი წერტილები საერთო რაოდენობაში შედის, მაგრამ რეგიონს არ მიეკუთვნება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'ენოტის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('procyon-lotor', 'en', 'Raccoon: where it is recorded in Georgia', 'The raccoon map uses public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions are not shaded. Points outside the regional polygons stay in the total but are not assigned to a region. Record counts reflect observation effort, not population density.', 'Raccoon observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('procyon-lotor', 'ru', 'Где енот-полоскун отмечен в Грузии', 'Карта енота-полоскуна использует публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей; остальные регионы не закрашены. Точки вне региональных полигонов входят в общее число, но к региону не относятся. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения енота-полоскуна и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('procyon-lotor', 'tr', 'Rakun Gürcistan''da nerede kaydedildi?', 'Rakun haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler boyanır; diğer bölgeler boyanmaz. Bölge poligonlarının dışında kalan noktalar toplama girer ama bir bölgeye yazılmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Rakun gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('pseudopus-apodus', 31975, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('pseudopus-apodus', 'ka', 'სად არის გველხოკერა დაფიქსირებული საქართველოში', 'რუკა იყენებს საქართველოში გველხოკერას შესახებ iNaturalist-ის საჯარო დაკვირვებებს. რუკაზე შეფერილია მხოლოდ რეგიონული ცხრილის მიხედვით საკმარისი ჩანაწერების მქონე რეგიონები; დანარჩენებში ჩანაწერები ცოტაა. 2026 წლის ჩამონათვალი აღმოსავლეთ საქართველოს ასახელებს, დაკვირვებების ცხრილში კი რუკის ჩანაწერთა ზღვარს აფხაზეთიც აღწევს. ჩანაწერების რაოდენობა პოპულაციის სიმჭიდროვეს არ ზომავს.', 'გველხოკერას დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('pseudopus-apodus', 'en', 'Where the European glass lizard is recorded in Georgia', 'This map uses public iNaturalist observations of the European glass lizard in Georgia. Its shaded regions are those with enough records in the records-by-region table; other regions have too few records. The 2026 checklist describes an eastern range, while Abkhazia also reaches this map''s record threshold in the observation table. Counts reflect observation effort, not population density.', 'European glass lizard observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('pseudopus-apodus', 'ru', 'Где желтопузик отмечен в Грузии', 'Карта использует публичные наблюдения желтопузика в Грузии на iNaturalist. На карте закрашены только регионы с достаточным числом записей в таблице; в остальных записей мало. Перечень 2026 года указывает восточную Грузию, а Абхазия также достигает порога записей на этой карте. Число записей не отражает плотность популяции.', 'Наблюдения желтопузика и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('pseudopus-apodus', 'tr', 'Yılan kertenkele Gürcistan''da nerede kaydedildi?', 'Bu harita, Gürcistan''daki yılan kertenkeleye ait herkese açık iNaturalist gözlemlerini kullanır. Haritada yalnızca bölgesel kayıt tablosunda yeterli kaydı olan bölgeler renklendirilir; diğerlerinde kayıt azdır. 2026 listesi Doğu Gürcistan''ı belirtirken Abhazya da bu haritadaki kayıt eşiğine ulaşır. Kayıt sayısı nüfus yoğunluğunu göstermez.', 'Yılan kertenkele gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('steatoda-paykulliana', 343356, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('steatoda-paykulliana', 'ka', 'სად არის ცრუ ყარაყურთი დაფიქსირებული საქართველოში', 'ცრუ ყარაყურთის რუკა იყენებს iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან და რუკაზე შეფერილია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები.', 'ცრუ ყარაყურთის გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('steatoda-paykulliana', 'en', 'False black widow: where it is recorded in Georgia', 'The false black widow map uses public iNaturalist observations. Regions are taken from the records-by-region table, and only regions with enough records are shaded on the map.', 'False black widow distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('steatoda-paykulliana', 'ru', 'Где ложный каракурт отмечен в Грузии', 'Карта ложного каракурта использует публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам; на карте закрашены только регионы с достаточным числом записей.', 'Данные о распространении ложного каракурта и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('steatoda-paykulliana', 'tr', 'Yalancı karakurt Gürcistan''da nerede kaydedildi?', 'Yalancı karakurt haritası herkese açık iNaturalist gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır; haritada yalnızca yeterli kaydı olan bölgeler boyanır.', 'Yalancı karakurtun Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('streptopelia-turtur', 2938, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('streptopelia-turtur', 'ka', 'სად არის გვრიტი დაფიქსირებული საქართველოში', 'გვრიტის რუკა საქართველოს iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე შეფერილია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები; დანარჩენი რეგიონები შეფერილი არ არის. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'გვრიტის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('streptopelia-turtur', 'en', 'European turtle dove: where it is recorded in Georgia', 'The European turtle dove map uses public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions are not shaded. Record counts reflect observation effort, not population density.', 'European turtle dove observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('streptopelia-turtur', 'ru', 'Где обыкновенная горлица отмечена в Грузии', 'Карта обыкновенной горлицы использует публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей; остальные регионы не закрашены. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения обыкновенной горлицы и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('streptopelia-turtur', 'tr', 'Üveyik Gürcistan''da nerede kaydedildi?', 'Üveyik haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler boyanır; diğer bölgeler boyanmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Üveyik gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('telescopus-fallax', 64078, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('telescopus-fallax', 'ka', 'სად არის კატისთვალა დაფიქსირებული საქართველოში', 'კატისთვალას რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებს, ხელით შერჩეულ ლოკალიტეტებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან, ხოლო სტატუსი ერთმანეთისგან გამოყოფს საკმარისი ჩანაწერების მქონე რეგიონებსა და რეგიონებს, სადაც ჩანაწერები ცოტაა.', 'კატისთვალას გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('telescopus-fallax', 'en', 'European cat snake: where it is recorded in Georgia', 'The European cat snake map combines Reptiles.ge editorial photo records, hand-curated localities, and public iNaturalist observations. Regions are taken from the records-by-region table, and the status column separates regions with enough records from regions with too few records.', 'European cat snake distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('telescopus-fallax', 'ru', 'Где европейский кошачий уж отмечен в Грузии', 'Карта европейского кошачьего ужа объединяет редакционные фотозаписи Reptiles.ge, вручную отобранные локалитеты и публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам, а статус отделяет регионы с достаточным числом записей от регионов, где записей мало.', 'Данные о распространении европейского кошачьего ужа и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('telescopus-fallax', 'tr', 'Avrupa kedi yılanı Gürcistan''da nerede kaydedildi?', 'Avrupa kedi yılanı haritası Reptiles.ge editoryal fotoğraf kayıtlarını, elle seçilmiş lokaliteleri ve herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; durum sütunu yeterli kaydı olan bölgeleri kaydı az olan bölgelerden ayırır.', 'Avrupa kedi yılanının Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('testudo-graeca', 40023, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('testudo-graeca', 'ka', 'სად არის ხმელთაშუაზღვეთის კუ დაფიქსირებული საქართველოში', 'ხმელთაშუაზღვეთის კუს რუკა აჩვენებს iNaturalist-ის საჯარო დაკვირვებებს საქართველოში. რუკაზე მხოლოდ ის რეგიონებია გამოკვეთილი, რომლებსაც ჩანაწერების ცხრილში საკმარისი ჩანაწერი აქვს. iNaturalist ამ სახეობის საჯარო კოორდინატებს ფარავს, ამიტომ წერტილები მიახლოებითია: ზოგი საზღვარს გადაღმა ან მეზობელ რეგიონში ხვდება, ხოლო რეგიონების საზღვრებს გარეთ მოხვედრილი წერტილები ცხრილში არ ითვლება. დასავლეთ საქართველოს რეგიონები, სადაც მხოლოდ ცალკეული ჩანაწერია, გამოკვეთილი არ არის. გამოკვეთილი რეგიონი არ ნიშნავს მის მთელ ტერიტორიაზე გავრცელებას; ჩანაწერების რაოდენობა პოპულაციის სიმჭიდროვეს არ ზომავს.', 'ხმელთაშუაზღვეთის კუს საველე ჩანაწერები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('testudo-graeca', 'en', 'Where Mediterranean tortoises are recorded in Georgia', 'The Mediterranean tortoise map shows public iNaturalist observations in Georgia. Only regions with enough records in the records table are shaded on the map. iNaturalist obscures the public coordinates of this species, so points are approximate, some fall across a border or a regional boundary, and those outside the region outlines are not counted. Regions in the west with single records are not shaded. A shaded region does not mean the tortoise occupies all of it; record counts reflect observation effort, not population density.', 'Mediterranean tortoise field records and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('testudo-graeca', 'ru', 'Где средиземноморская черепаха отмечена в Грузии', 'Карта средиземноморской черепахи показывает публичные наблюдения iNaturalist в Грузии. На карте выделены только регионы с достаточным числом записей в таблице записей. iNaturalist скрывает публичные координаты этого вида, поэтому точки приблизительны: некоторые попадают за границу или в соседний регион, а точки за границами регионов в таблице не учитываются. Регионы запада Грузии с единичными записями не выделены. Выделенный регион не означает присутствие на всей его территории; число записей не измеряет плотность популяции.', 'Полевые записи средиземноморской черепахи и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('testudo-graeca', 'tr', 'Akdeniz tosbağası Gürcistan''da nerede kaydedildi?', 'Akdeniz tosbağası haritası Gürcistan''daki herkese açık iNaturalist gözlemlerini gösterir. Haritada yalnızca kayıt tablosunda yeterli kaydı olan bölgeler vurgulanır. iNaturalist bu türün açık koordinatlarını gizler; bu yüzden noktalar yaklaşıktır, bazıları sınırın ötesine veya komşu bölgeye düşer ve bölge sınırları dışında kalan noktalar tabloda sayılmaz. Batı Gürcistan''da yalnızca tekil kaydı olan bölgeler vurgulanmaz. Vurgulanan bölge, türün o bölgenin her yerinde bulunduğu anlamına gelmez; kayıt sayısı popülasyon yoğunluğunu ölçmez.', 'Akdeniz tosbağasının arazi kayıtları ve kayıt bulunan bölgeleri Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('trachemys-scripta', 39782, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('trachemys-scripta', 'ka', 'სად არის წითელყურა კუ დაფიქსირებული საქართველოში', 'წითელყურა კუს რუკა აჩვენებს iNaturalist-ის საჯარო დაკვირვებებს საქართველოში. რუკაზე მხოლოდ ის რეგიონებია გამოკვეთილი, რომლებსაც ჩანაწერების ცხრილში საკმარისი ჩანაწერი აქვს: თბილისი, აჭარა და აფხაზეთი. იმერეთი, ქვემო ქართლი და გურია, სადაც მხოლოდ ცალკეული ჩანაწერია, გამოკვეთილი არ არის. წითელყურა კუ შემოტანილი სახეობაა, ამიტომ ჩანაწერი შეიძლება გაშვებულ ან გაქცეულ შინაურ კუს ეკუთვნოდეს და თავისთავად გამრავლებად პოპულაციას არ ადასტურებს. გამოკვეთილი რეგიონი არ ნიშნავს მის მთელ ტერიტორიაზე გავრცელებას; ჩანაწერების რაოდენობა პოპულაციის სიმჭიდროვეს არ ზომავს.', 'წითელყურა კუს საველე ჩანაწერები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('trachemys-scripta', 'en', 'Where pond sliders are recorded in Georgia', 'The pond slider map shows public iNaturalist observations in Georgia. Only regions with enough records in the records table are shaded on the map: Tbilisi, Adjara, and Abkhazia. Imereti, Kvemo Kartli, and Guria have single records and are not shaded. The pond slider is an introduced species, so a record can be a released or escaped pet and does not by itself show a reproducing population. A shaded region does not mean the turtle lives everywhere in it; record counts reflect observation effort, not population density.', 'Pond slider field records and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('trachemys-scripta', 'ru', 'Где красноухая черепаха отмечена в Грузии', 'Карта красноухой черепахи показывает публичные наблюдения iNaturalist в Грузии. На карте выделены только регионы с достаточным числом записей в таблице записей: Тбилиси, Аджария и Абхазия. Имеретия, Квемо Картли и Гурия, где есть лишь единичные записи, не выделены. Красноухая черепаха — интродуцированный вид, поэтому запись может относиться к выпущенной или сбежавшей домашней черепахе и сама по себе не подтверждает размножающуюся популяцию. Выделенный регион не означает присутствие на всей его территории; число записей не измеряет плотность популяции.', 'Полевые записи красноухой черепахи и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('trachemys-scripta', 'tr', 'Kırmızı yanaklı su kaplumbağası Gürcistan''da nerede kaydedildi?', 'Kırmızı yanaklı su kaplumbağası haritası Gürcistan''daki herkese açık iNaturalist gözlemlerini gösterir. Haritada yalnızca kayıt tablosunda yeterli kaydı olan bölgeler vurgulanır: Tiflis, Acara ve Abhazya. Yalnızca tekil kaydı olan İmereti, Kvemo Kartli ve Gurya vurgulanmaz. Kırmızı yanaklı su kaplumbağası sokulmuş bir türdür; bu yüzden bir kayıt doğaya bırakılmış veya kaçmış bir evcil hayvana ait olabilir ve tek başına üreyen bir popülasyonu göstermez. Vurgulanan bölge, türün o bölgenin her yerinde bulunduğu anlamına gelmez; kayıt sayısı popülasyon yoğunluğunu ölçmez.', 'Kırmızı yanaklı su kaplumbağasının arazi kayıtları ve kayıt bulunan bölgeleri Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('turdus-merula', 12716, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('turdus-merula', 'ka', 'სად არის შავი შაშვი დაფიქსირებული საქართველოში', 'შავი შაშვის რუკა საქართველოს iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე შეფერილია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები; დანარჩენი რეგიონები შეფერილი არ არის. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'შავი შაშვის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('turdus-merula', 'en', 'Common blackbird: where it is recorded in Georgia', 'The common blackbird map uses public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions are not shaded. Record counts reflect observation effort, not population density.', 'Common blackbird observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('turdus-merula', 'ru', 'Где чёрный дрозд отмечен в Грузии', 'Карта чёрного дрозда использует публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей; остальные регионы не закрашены. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения чёрного дрозда и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('turdus-merula', 'tr', 'Karatavuk Gürcistan''da nerede kaydedildi?', 'Karatavuk haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler boyanır; diğer bölgeler boyanmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Karatavuk gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('tyto-alba', 20445, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('tyto-alba', 'ka', 'სად არის ბუხრინწა დაფიქსირებული საქართველოში', 'ბუხრინწას რუკა საქართველოს iNaturalist-ის საჯარო ფოტოდაკვირვებებს ეყრდნობა. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე შეფერილია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები; დანარჩენი რეგიონები შეფერილი არ არის. ცალკეული დაკვირვების ადგილის წარწერა კოორდინატს რომ არ ემთხვევა, ეს წარწერა იმ რეგიონის ჩანაწერად არ ითვლება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'ბუხრინწას დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', 'რეგიონი ჩანაწერით', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('tyto-alba', 'en', 'Western barn owl: where it is recorded in Georgia', 'The western barn owl map uses public iNaturalist photo observations in Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map; other regions are not shaded. Some place names on individual observations do not match the coordinate, and a mismatched label does not count as a record for that named region. Record counts reflect observation effort, not population density.', 'Western barn owl observations and regions with records on a map of Georgia', 'Region with records', 'regions with records', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('tyto-alba', 'ru', 'Где сипуха отмечена в Грузии', 'Карта сипухи использует публичные фотонаблюдения iNaturalist в Грузии. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей; остальные регионы не закрашены. Если подпись места у отдельного наблюдения не совпадает с координатой, эта подпись не считается записью для названного региона. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения сипухи и регионы с записями на карте Грузии', 'Регион с записями', 'регионов с записями', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('tyto-alba', 'tr', 'Peçeli baykuş Gürcistan''da nerede kaydedildi?', 'Peçeli baykuş haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler boyanır; diğer bölgeler boyanmaz. Tek bir gözlemin yer adı koordinatla uyuşmuyorsa bu ad o bölge için kayıt sayılmaz. Kayıt sayısı nüfus yoğunluğunu değil, gözlem çabasını yansıtır.', 'Peçeli baykuş gözlemleri ve Gürcistan''da kayıt bulunan bölgeler', 'Kayıt bulunan bölge', 'kayıt bulunan bölge', NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('ursus-arctos', 41641, 'record-summary', 8);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('ursus-arctos', 'ka', 'სად არის მურა დათვი დაფიქსირებული საქართველოში', 'მურა დათვის რუკა იყენებს iNaturalist-ის საჯარო ფოტოდაკვირვებებს საქართველოდან. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან: რუკაზე შეფერილია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები, ხოლო მცირე რაოდენობის ან გაურკვეველი ჩანაწერების რეგიონები შეფერილი არ არის. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და პოპულაციის სიმჭიდროვეს არ ზომავს.', 'მურა დათვის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('ursus-arctos', 'en', 'Brown bear: where it is recorded in Georgia', 'The brown bear map uses public iNaturalist photo observations from Georgia. Regions come from the records-by-region table: only regions with enough records are shaded on the map, while low-count or uncertain regions are not shaded. Record counts reflect observation effort, not population density.', 'Brown bear observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('ursus-arctos', 'ru', 'Где бурый медведь отмечен в Грузии', 'Карта бурого медведя использует публичные фотонаблюдения iNaturalist из Грузии. Регионы взяты из таблицы записей: на карте закрашены только регионы с достаточным числом записей, а регионы с малым числом или неопределёнными записями не закрашены. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения бурого медведя и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('ursus-arctos', 'tr', 'Boz ayı Gürcistan''da nerede kaydedildi?', 'Boz ayı haritası Gürcistan''daki herkese açık iNaturalist fotoğraf gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır: haritada yalnızca yeterli kaydı olan bölgeler boyanır; az sayıdaki veya belirsiz kayıtların bulunduğu bölgeler boyanmaz. Kayıt sayısı gözlem çabasını yansıtır, nüfus yoğunluğunu ölçmez.', 'Boz ayı gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('vipera-darevskii', 73995, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('vipera-darevskii', 'ka', 'სად არის დარევსკის გველგესლა დაფიქსირებული საქართველოში', 'დარევსკის გველგესლას რუკა იყენებს iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან; რუკაზე შეფერილია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები, ხოლო რეგიონები, სადაც ჩანაწერები ცოტაა, შეფერილი არ არის.', 'დარევსკის გველგესლას დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('vipera-darevskii', 'en', 'Darevsky''s viper: where it is recorded in Georgia', 'The Darevsky''s viper map uses public iNaturalist observations. Regions are taken from the records-by-region table; only regions with enough records are shaded on the map, while regions with too few records are not.', 'Darevsky''s viper observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('vipera-darevskii', 'ru', 'Где гадюка Даревского отмечена в Грузии', 'Карта гадюки Даревского использует публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам; на карте закрашены только регионы с достаточным числом записей, а регионы, где записей мало, не закрашены.', 'Наблюдения гадюки Даревского и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('vipera-darevskii', 'tr', 'Darevsky engereği Gürcistan''da nerede kaydedildi?', 'Darevsky engereği haritası herkese açık iNaturalist gözlemlerini kullanır. Bölgeler, bölgelere göre kayıt tablosundan alınır; haritada yalnızca yeterli kaydı olan bölgeler boyanır, kaydı az olan bölgeler boyanmaz.', 'Darevsky engereğinin gözlemleri ve kayıt bulunan bölgeleri Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('vipera-dinniki', 73996, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('vipera-dinniki', 'ka', 'სად არის დინიკის გველგესლა დაფიქსირებული საქართველოში', 'დინიკის გველგესლას რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან და რუკაზე შეფერილია მხოლოდ საკმარისი ჩანაწერების მქონე რეგიონები; ჩანაწერების რაოდენობა პოპულაციის სიმჭიდროვეს არ ზომავს.', 'დინიკის გველგესლას გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('vipera-dinniki', 'en', 'Dinnik''s viper: where it is recorded in Georgia', 'The Dinnik''s viper map combines Reptiles.ge editorial photo records with public iNaturalist observations. Regions are taken from the records-by-region table, and only regions with enough records are shaded on the map; record counts do not measure population density.', 'Dinnik''s viper distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('vipera-dinniki', 'ru', 'Где гадюка Динника отмечена в Грузии', 'Карта гадюки Динника объединяет редакционные фотозаписи Reptiles.ge и публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам; на карте закрашены только регионы с достаточным числом записей, а число записей не измеряет плотность популяции.', 'Данные о распространении гадюки Динника и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('vipera-dinniki', 'tr', 'Dinnik engereği Gürcistan''da nerede kaydedildi?', 'Dinnik engereği haritası Reptiles.ge editoryal fotoğraf kayıtlarını ve herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; haritada yalnızca yeterli kaydı olan bölgeler boyanır ve kayıt sayısı popülasyon yoğunluğunu ölçmez.', 'Dinnik engereğinin Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('vipera-kaznakovi', 73999, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('vipera-kaznakovi', 'ka', 'სად არის კავკასიური გველგესლა დაფიქსირებული საქართველოში', 'კავკასიური გველგესლის რუკა აერთიანებს Reptiles.ge-ის სარედაქციო ფოტოჩანაწერებს, ხელით შერჩეულ ლოკალიტეტებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონები აღებულია ჩანაწერების რეგიონული ცხრილიდან, ხოლო სტატუსი ერთმანეთისგან გამოყოფს საკმარისი ჩანაწერების მქონე რეგიონებსა და რეგიონებს, სადაც ჩანაწერები ცოტაა.', 'კავკასიური გველგესლის გავრცელების მტკიცებულებები და საველე ჩანაწერები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('vipera-kaznakovi', 'en', 'Caucasus viper: where it is recorded in Georgia', 'The Caucasus viper map combines Reptiles.ge editorial photo records, hand-curated localities, and public iNaturalist observations. Regions are taken from the records-by-region table, and the status column separates regions with enough records from regions with too few records.', 'Caucasus viper distribution evidence and field records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('vipera-kaznakovi', 'ru', 'Где кавказская гадюка отмечена в Грузии', 'Карта кавказской гадюки объединяет редакционные фотозаписи Reptiles.ge, вручную отобранные локалитеты и публичные наблюдения iNaturalist. Регионы взяты из таблицы записей по регионам, а статус отделяет регионы с достаточным числом записей от регионов, где записей мало.', 'Данные о распространении кавказской гадюки и полевые записи на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('vipera-kaznakovi', 'tr', 'Kafkas engereği Gürcistan''da nerede kaydedildi?', 'Kafkas engereği haritası Reptiles.ge editoryal fotoğraf kayıtlarını, elle seçilmiş lokaliteleri ve herkese açık iNaturalist gözlemlerini birleştirir. Bölgeler, bölgelere göre kayıt tablosundan alınır; durum sütunu yeterli kaydı olan bölgeleri kaydı az olan bölgelerden ayırır.', 'Kafkas engereğinin Gürcistan''daki yayılış kanıtları ve arazi kayıtları', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('vipera-renardi', 114991, 'record-summary', 1);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('vipera-renardi', 'ka', 'სად არის ველის გველგესლა დაფიქსირებული საქართველოში', 'ველის გველგესლას რუკა იყენებს iNaturalist-ის საჯარო დაკვირვებებს Vipera renardi-ზე. რეგიონი, სადაც სულ მცირე ერთი საველე ჩანაწერია, რუკაზე შეფერილია; ჩანაწერის არმქონე რეგიონი შეფერილი არ არის. საჯარო კოორდინატების ნაწილი დაფარულია, ამიტომ რეგიონების საზღვართან წერტილები მიახლოებითია. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და პოპულაციის სიმჭიდროვეს არ ზომავს.', 'ველის გველგესლას დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('vipera-renardi', 'en', 'Steppe viper: where it is recorded in Georgia', 'The steppe viper map uses public iNaturalist observations of Vipera renardi. A region with at least one field record is shaded on the map; a region with no records is not shaded. Some public coordinates are obscured, so points near regional borders are approximate. Record counts reflect observation effort, not population density.', 'Steppe viper observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('vipera-renardi', 'ru', 'Где степная гадюка отмечена в Грузии', 'Карта степной гадюки использует публичные наблюдения iNaturalist для Vipera renardi. Регион хотя бы с одной полевой записью закрашен на карте; регион без записей не закрашен. Часть публичных координат скрыта, поэтому точки у границ регионов приблизительны. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения степной гадюки и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('vipera-renardi', 'tr', 'Bozkır engereği Gürcistan''da nerede kaydedildi?', 'Bozkır engereği haritası Vipera renardi için herkese açık iNaturalist gözlemlerini kullanır. En az bir arazi kaydı olan bölge haritada boyanır; kaydı olmayan bölge boyanmaz. Bazı halka açık koordinatlar gizlendiğinden bölge sınırlarına yakın noktalar yaklaşıktır. Kayıt sayısı gözlem çabasını yansıtır, nüfus yoğunluğunu ölçmez.', 'Bozkır engereğinin gözlemleri ve kayıt bulunan bölgeleri Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('vipera-transcaucasiana', 1701183, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('vipera-transcaucasiana', 'ka', 'სად არის ცხვირრქოსანი გველგესლა დაფიქსირებული საქართველოში', 'ცხვირრქოსანი გველგესლას რუკა იყენებს iNaturalist-ის საჯარო დაკვირვებებს, რომლებიც Vipera meridionalis transcaucasiana-ს სახელითაა შეტანილი. რუკაზე შეფერილია მხოლოდ ცხრილის მიხედვით საკმარისი ჩანაწერების მქონე რეგიონები. საჯარო კოორდინატები დაფარულია, ამიტომ რეგიონების საზღვართან წერტილები მიახლოებითია; ჩანაწერების რაოდენობა პოპულაციის სიმჭიდროვეს არ ზომავს.', 'ცხვირრქოსანი გველგესლას დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('vipera-transcaucasiana', 'en', 'Where the nose-horned viper is recorded in Georgia', 'The nose-horned viper map uses public iNaturalist observations filed as Vipera meridionalis transcaucasiana. Only regions with enough records in the records table are shaded on the map. Public coordinates are obscured, so points near regional borders are approximate; record counts do not measure population density.', 'Nose-horned viper observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('vipera-transcaucasiana', 'ru', 'Где носатая гадюка отмечена в Грузии', 'Карта носатой гадюки использует публичные наблюдения iNaturalist под названием Vipera meridionalis transcaucasiana. На карте закрашены только регионы с достаточным числом записей в таблице. Публичные координаты скрыты, поэтому точки у границ регионов приблизительны; число записей не измеряет плотность популяции.', 'Наблюдения носатой гадюки и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('vipera-transcaucasiana', 'tr', 'Boynuzlu engerek Gürcistan''da nerede kaydedildi?', 'Boynuzlu engerek haritası, iNaturalist''te Vipera meridionalis transcaucasiana adıyla kayıtlı halka açık gözlemleri kullanır. Haritada yalnızca tabloda yeterli kaydı olan bölgeler boyanır. Halka açık koordinatlar gizlendiğinden bölge sınırlarına yakın noktalar yaklaşıktır; kayıt sayısı popülasyon yoğunluğunu ölçmez.', 'Boynuzlu engerek gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('vulpes-vulpes', 42069, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('vulpes-vulpes', 'ka', 'სად არის მელა დაფიქსირებული საქართველოში', 'მელას რუკა იყენებს საქართველოში გაკეთებულ iNaturalist-ის საჯარო ფოტოდაკვირვებებს. რუკაზე შეფერილია მხოლოდ რეგიონი, რომელსაც ქვემოთ მოცემულ ცხრილში საკმარისი ჩანაწერები აქვს; სხვა წერტილები ცალკეული ჩანაწერებია. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'მელას საველე ჩანაწერები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('vulpes-vulpes', 'en', 'Red fox: where it is recorded in Georgia', 'The red fox map uses public iNaturalist photo observations from Georgia. Only regions with enough records in the records-by-region table are shaded on the map; other points are individual records. Record counts reflect observation effort, not population density.', 'Red fox field records and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('vulpes-vulpes', 'ru', 'Где лисица отмечена в Грузии', 'Карта лисицы использует публичные фотонаблюдения iNaturalist из Грузии. На карте окрашены только регионы с достаточным числом записей в таблице; остальные точки — отдельные находки. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Полевые записи лисицы и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('vulpes-vulpes', 'tr', 'Kızıl tilki Gürcistan''da nerede kaydedildi?', 'Kızıl tilki haritası Gürcistan''daki herkese açık iNaturalist fotoğraflı gözlemlerini kullanır. Haritada yalnızca kayıt tablosunda yeterli kaydı olan bölgeler boyanır; diğer noktalar tekil kayıtlardır. Kayıt sayısı gözlem çabasını yansıtır, nüfus yoğunluğunu değil.', 'Kızıl tilkinin Gürcistan''daki arazi kayıtları ve kayıt bulunan bölgeleri', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('xerotyphlops-vermicularis', 514727, 'record-summary', NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('xerotyphlops-vermicularis', 'ka', 'სად არის გველბრუცა დაფიქსირებული საქართველოში', 'გველბრუცას რუკა საქართველოს iNaturalist-ის საჯარო დაკვირვებებს ეყრდნობა. გამოკვეთილია მხოლოდ ის რეგიონები, რომლებსაც ჩანაწერების რეგიონულ ცხრილში საკმარისი ჩანაწერები აქვთ; ცალკეული ჩანაწერი მთელი რეგიონის გავრცელებას არ ნიშნავს. ზოგი საჯარო კოორდინატი დაფარულია და რეგიონის ჩანაწერებში არ ითვლება. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და არა პოპულაციის სიმჭიდროვეს.', 'გველბრუცას დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('xerotyphlops-vermicularis', 'en', 'European blind snake: where it is recorded in Georgia', 'The European blind snake map uses public iNaturalist observations in Georgia. Only regions with enough records in the records-by-region table are highlighted; isolated records do not establish region-wide distribution. Some public coordinates are obscured and do not count toward a region''s records. Record counts reflect observation effort, not population density.', 'European blind snake observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('xerotyphlops-vermicularis', 'ru', 'Где червеобразная слепозмейка отмечена в Грузии', 'Карта червеобразной слепозмейки основана на публичных наблюдениях iNaturalist в Грузии. Выделены только регионы с достаточным числом записей в таблице; отдельная запись не означает распространение по всему региону. Некоторые публичные координаты скрыты и не учитываются в записях региона. Число записей отражает активность наблюдателей, не плотность популяции.', 'Наблюдения червеобразной слепозмейки и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('xerotyphlops-vermicularis', 'tr', 'Kör yılan Gürcistan''da nerede kaydedildi?', 'Kör yılan haritası Gürcistan''daki herkese açık iNaturalist gözlemlerini kullanır. Yalnızca bölgesel kayıt tablosunda yeterli kaydı olan bölgeler vurgulanır; tek bir kayıt tüm bölgede yayılış anlamına gelmez. Bazı halka açık koordinatlar gizlenmiştir ve bölgenin kayıtlarına sayılmaz. Kayıt sayısı gözlem çabasını yansıtır, popülasyon yoğunluğunu ölçmez.', 'Kör yılan gözlemleri ve kayıt bulunan bölgeler Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('zamenis-hohenackeri', 74007, 'record-summary', 1);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('zamenis-hohenackeri', 'ka', 'სად არის ამიერკავკასიური მცურავი დაფიქსირებული საქართველოში', 'ამიერკავკასიური მცურავის რუკა აერთიანებს Reptiles.ge-ის საველე ფოტოებსა და iNaturalist-ის საჯარო დაკვირვებებს. რეგიონი, სადაც სულ მცირე ერთი საველე ჩანაწერია, რუკაზე შეფერილია. iNaturalist-ის ზოგი კოორდინატი დაფარულია, ამიტომ რეგიონების საზღვრებთან მდებარე წერტილები მიახლოებითია. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და პოპულაციის სიმჭიდროვეს არ ზომავს.', 'ამიერკავკასიური მცურავის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('zamenis-hohenackeri', 'en', 'Transcaucasian rat snake: where it is recorded in Georgia', 'The Transcaucasian rat snake map combines Reptiles.ge field photos with public iNaturalist observations. A region with at least one field record is shaded on the map. Some iNaturalist coordinates are obscured, so points near regional borders are approximate. Record counts reflect observation effort, not population density.', 'Transcaucasian rat snake observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('zamenis-hohenackeri', 'ru', 'Где закавказский полоз отмечен в Грузии', 'Карта закавказского полоза объединяет полевые фотографии Reptiles.ge и публичные наблюдения iNaturalist. Регион хотя бы с одной полевой записью закрашен на карте. Координаты некоторых наблюдений iNaturalist скрыты, поэтому точки у границ регионов приблизительны. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения закавказского полоза и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('zamenis-hohenackeri', 'tr', 'Transkafkas sıçan yılanı Gürcistan''da nerede kaydedildi?', 'Transkafkas sıçan yılanı haritası Reptiles.ge arazi fotoğraflarını ve herkese açık iNaturalist gözlemlerini birleştirir. En az bir saha kaydı olan bölge haritada boyanır. Bazı iNaturalist koordinatları gizlendiğinden bölge sınırlarındaki noktalar yaklaşıktır. Kayıt sayısı gözlem çabasını yansıtır, nüfus yoğunluğunu ölçmez.', 'Transkafkas sıçan yılanının gözlemleri ve kayıt bulunan bölgeleri Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL);
INSERT INTO species_range_maps (species_id, inaturalist_taxon_id, range_source, confirmed_threshold) VALUES ('zamenis-longissimus', 74009, 'record-summary', 1);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('zamenis-longissimus', 'ka', 'სად არის ესკულაპის მცურავი დაფიქსირებული საქართველოში', 'ესკულაპის მცურავის რუკა იყენებს iNaturalist-ის საჯარო დაკვირვებებს Zamenis longissimus-ზე. რეგიონი, სადაც სულ მცირე ერთი საველე ჩანაწერია, რუკაზე შეფერილია; ჩანაწერის არმქონე რეგიონი შეფერილი არ არის. საჯარო კოორდინატების ნაწილი დაფარულია, ამიტომ რეგიონების საზღვართან წერტილები მიახლოებითია. ჩანაწერების რაოდენობა დაკვირვების ინტენსივობას ასახავს და პოპულაციის სიმჭიდროვეს არ ზომავს.', 'ესკულაპის მცურავის დაკვირვებები და ჩანაწერების მქონე რეგიონები საქართველოს რუკაზე', 'ჩანაწერების მქონე რეგიონი', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('zamenis-longissimus', 'en', 'Aesculapian snake: where it is recorded in Georgia', 'The Aesculapian snake map uses public iNaturalist observations of Zamenis longissimus. A region with at least one field record is shaded on the map; a region with no records is not shaded. Some public coordinates are obscured, so points near regional borders are approximate. Record counts reflect observation effort, not population density.', 'Aesculapian snake observations and regions with records on a map of Georgia', 'Region with records', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('zamenis-longissimus', 'ru', 'Где эскулапов полоз отмечен в Грузии', 'Карта эскулапова полоза использует публичные наблюдения iNaturalist для Zamenis longissimus. Регион хотя бы с одной полевой записью закрашен на карте; регион без записей не закрашен. Часть публичных координат скрыта, поэтому точки у границ регионов приблизительны. Число записей отражает активность наблюдателей, а не плотность популяции.', 'Наблюдения эскулапова полоза и регионы с записями на карте Грузии', 'Регион с записями', NULL, NULL);
INSERT INTO species_range_map_texts (species_id, locale, range_title, intro, map_aria, official_region_label, regions_metric_label, confirmed_status_label) VALUES ('zamenis-longissimus', 'tr', 'Eskülap yılanı Gürcistan''da nerede kaydedildi?', 'Eskülap yılanı haritası Zamenis longissimus için herkese açık iNaturalist gözlemlerini kullanır. En az bir arazi kaydı olan bölge haritada boyanır; kaydı olmayan bölge boyanmaz. Bazı halka açık koordinatlar gizlendiğinden bölge sınırlarına yakın noktalar yaklaşıktır. Kayıt sayısı gözlem çabasını yansıtır, nüfus yoğunluğunu ölçmez.', 'Eskülap yılanının gözlemleri ve kayıt bulunan bölgeleri Gürcistan haritasında', 'Kayıt bulunan bölge', NULL, NULL);
